-- ==== 20261016000002_integrity_and_rls.sql ====
-- Integrity triggers (history protection) and row-level security.

-- ---------------------------------------------------------------------------
-- Published content is immutable outside the correction workflow.
-- ---------------------------------------------------------------------------
create or replace function pricele.guard_published_question()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    if old.status = 'published' or exists (
      select 1 from public.daily_set_questions where question_id = old.id
    ) then
      raise exception 'PRICELE_IMMUTABLE: questions assigned to a daily set cannot be deleted';
    end if;
    return old;
  end if;

  if old.status = 'published' and (
       new.prompt is distinct from old.prompt
    or new.context is distinct from old.context
    or new.difficulty is distinct from old.difficulty
    or new.category_id is distinct from old.category_id
    or new.image_url is distinct from old.image_url
    or new.status is distinct from old.status and coalesce(current_setting('pricele.allow_status_change', true), '') <> 'on'
  ) then
    raise exception 'PRICELE_IMMUTABLE: published questions cannot be edited; use the correction workflow';
  end if;
  return new;
end;
$$;

create trigger questions_guard_published
  before update or delete on public.questions
  for each row execute function pricele.guard_published_question();

create or replace function pricele.guard_published_answer()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_status text;
begin
  select status into v_status from public.questions where id = coalesce(new.question_id, old.question_id);
  if v_status = 'published' then
    if tg_op = 'DELETE' then
      raise exception 'PRICELE_IMMUTABLE: answer keys of published questions cannot be deleted';
    end if;
    if (new.answer_amount is distinct from old.answer_amount
        or new.answer_definition is distinct from old.answer_definition
        or new.reference_date is distinct from old.reference_date
        or new.verification_status is distinct from old.verification_status)
       and coalesce(current_setting('pricele.correction_in_progress', true), '') <> 'on' then
      raise exception 'PRICELE_IMMUTABLE: published answers change only through the correction workflow';
    end if;
  end if;
  return coalesce(new, old);
end;
$$;

create trigger question_answers_guard_published
  before update or delete on public.question_answers
  for each row execute function pricele.guard_published_answer();

create or replace function pricele.guard_published_source()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if exists (select 1 from public.questions where id = old.question_id and status = 'published') then
    raise exception 'PRICELE_IMMUTABLE: sources of published questions cannot be removed or edited';
  end if;
  return coalesce(new, old);
end;
$$;

create trigger question_sources_guard_published
  before update or delete on public.question_sources
  for each row execute function pricele.guard_published_source();

-- Daily set membership is frozen once a set is scheduled/published, and the
-- position must match the question's difficulty (1=easy, 2=medium, 3=hard).
create or replace function pricele.guard_daily_set_questions()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_set_status text;
  v_difficulty text;
  v_q_status text;
begin
  select status into v_set_status from public.daily_sets
   where id = coalesce(new.daily_set_id, old.daily_set_id);

  if v_set_status is distinct from 'draft' and v_set_status is not null then
    raise exception 'PRICELE_IMMUTABLE: questions of a % daily set cannot change', v_set_status;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    select difficulty, status into v_difficulty, v_q_status from public.questions where id = new.question_id;
    if v_q_status is distinct from 'approved' then
      raise exception 'PRICELE_INVALID: only approved questions can be assigned to a daily set';
    end if;
    if new.position <> (case v_difficulty when 'easy' then 1 when 'medium' then 2 else 3 end) then
      raise exception 'PRICELE_INVALID: position % does not match difficulty %', new.position, v_difficulty;
    end if;
  end if;
  return coalesce(new, old);
end;
$$;

create trigger daily_set_questions_guard
  before insert or update or delete on public.daily_set_questions
  for each row execute function pricele.guard_daily_set_questions();

-- Prevent deleting published history.
create or replace function pricele.guard_daily_set_delete()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if old.status in ('scheduled', 'published') then
    raise exception 'PRICELE_IMMUTABLE: published daily sets cannot be deleted';
  end if;
  return old;
end;
$$;

create trigger daily_sets_guard_delete
  before delete on public.daily_sets
  for each row execute function pricele.guard_daily_set_delete();

-- ---------------------------------------------------------------------------
-- Live-content helper used by RLS (security definer avoids recursive policies).
-- ---------------------------------------------------------------------------
create or replace function pricele.now()
returns timestamptz
language sql
stable
set search_path = ''
as $$
  -- pricele.test_now lets the automated test suite simulate dates. The server role cannot
  -- set it for other sessions, and production code never sets it.
  select coalesce(nullif(current_setting('pricele.test_now', true), '')::timestamptz, now());
$$;

create or replace function pricele.current_game_date()
returns date
language sql
stable
set search_path = ''
as $$
  select (pricele.now() at time zone 'America/New_York')::date;
$$;

create or replace function pricele.is_set_live(p_set_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.daily_sets
     where id = p_set_id
       and status in ('scheduled', 'published')
       and game_date <= pricele.current_game_date()
  );
$$;

create or replace function pricele.is_question_live(p_question_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.daily_set_questions dsq
      join public.daily_sets ds on ds.id = dsq.daily_set_id
     where dsq.question_id = p_question_id
       and ds.status in ('scheduled', 'published')
       and ds.game_date <= pricele.current_game_date()
  );
$$;

-- ---------------------------------------------------------------------------
-- Privileges. Supabase grants broad default privileges to anon/authenticated on
-- new public tables; revoke everything and grant back only what is intended.
-- ---------------------------------------------------------------------------
revoke all on all tables in schema public from anon, authenticated;
revoke all on all functions in schema pricele from public;
alter default privileges in schema pricele revoke execute on functions from public;

grant usage on schema pricele to anon, authenticated;
grant execute on function pricele.is_set_live(uuid) to anon, authenticated;
grant execute on function pricele.is_question_live(uuid) to anon, authenticated;
grant execute on function pricele.now() to anon, authenticated;
grant execute on function pricele.current_game_date() to anon, authenticated;

-- Enable RLS on every table.
alter table public.categories enable row level security;
alter table public.profiles enable row level security;
alter table public.user_roles enable row level security;
alter table public.user_moderation enable row level security;
alter table public.questions enable row level security;
alter table public.question_answers enable row level security;
alter table public.question_sources enable row level security;
alter table public.daily_sets enable row level security;
alter table public.daily_set_questions enable row level security;
alter table public.guest_sessions enable row level security;
alter table public.official_attempts enable row level security;
alter table public.daily_results enable row level security;
alter table public.practice_attempts enable row level security;
alter table public.question_corrections enable row level security;
alter table public.official_attempt_revisions enable row level security;
alter table public.question_reports enable row level security;
alter table public.admin_audit_log enable row level security;
alter table public.rate_limits enable row level security;

-- Public, safe, player-facing content.
grant select on public.categories to anon, authenticated;
create policy categories_public_read on public.categories
  for select to anon, authenticated using (is_active);

grant select (id, game_date, status) on public.daily_sets to anon, authenticated;
create policy daily_sets_live_read on public.daily_sets
  for select to anon, authenticated using (pricele.is_set_live(id));

grant select (daily_set_id, question_id, position) on public.daily_set_questions to anon, authenticated;
create policy daily_set_questions_live_read on public.daily_set_questions
  for select to anon, authenticated using (pricele.is_set_live(daily_set_id));

grant select (id, prompt, context, difficulty, category_id, image_url, image_alt, image_credit)
  on public.questions to anon, authenticated;
create policy questions_live_read on public.questions
  for select to anon, authenticated using (pricele.is_question_live(id));

-- Public profiles expose only non-sensitive columns.
grant select (id, username, display_name, avatar_url, created_at) on public.profiles to anon, authenticated;
create policy profiles_public_read on public.profiles
  for select to anon, authenticated using (is_public);
grant select (is_public, updated_at) on public.profiles to authenticated;
create policy profiles_self_read on public.profiles
  for select to authenticated using (id = auth.uid());

-- Players may read their own official results/attempts. They can never write them.
grant select on public.daily_results to authenticated;
create policy daily_results_self_read on public.daily_results
  for select to authenticated using (user_id = auth.uid());

grant select on public.official_attempts to authenticated;
create policy official_attempts_self_read on public.official_attempts
  for select to authenticated using (user_id = auth.uid());

grant select on public.practice_attempts to authenticated;
create policy practice_attempts_self_read on public.practice_attempts
  for select to authenticated using (user_id = auth.uid());

-- Deliberately NO grants or policies for: question_answers, question_sources (until reveal),
-- user_roles, user_moderation, guest_sessions, question_corrections, official_attempt_revisions,
-- question_reports, admin_audit_log, rate_limits. These are reachable only through
-- privileged functions in the private pricele schema, which only pricele_app may execute.

-- ==== 20261016000003_game_functions.sql ====
-- Player-facing game logic. Every function here is SECURITY DEFINER, uses an empty
-- search_path with fully-qualified names, and is executable only by pricele_app.
-- Identity is supplied by the trusted Next.js server: either an authenticated user id
-- (verified with Supabase Auth on the server) or the SHA-256 hash of a guest cookie token.

-- ---------------------------------------------------------------------------
-- Scoring (authoritative implementation; mirrored and parity-tested in lib/scoring)
-- ---------------------------------------------------------------------------
create or replace function pricele.scoring_version()
returns text language sql immutable set search_path = '' as $$ select 'log-v1'::text $$;

create or replace function pricele.max_amount()
returns numeric language sql immutable set search_path = '' as $$ select 1000000000000000::numeric $$;

-- S = round(1000 / (1 + |ln(G) - ln(A)|)), natural log, exact NUMERIC arithmetic.
create or replace function pricele.score(p_guess numeric, p_answer numeric)
returns integer
language plpgsql
immutable
set search_path = ''
as $$
begin
  if p_guess is null or p_answer is null or p_guess <= 0 or p_answer <= 0 then
    raise exception 'PRICELE_INVALID: guess and answer must be positive';
  end if;
  if p_guess > pricele.max_amount() or p_answer > pricele.max_amount() then
    raise exception 'PRICELE_INVALID: amount exceeds maximum';
  end if;
  return round(1000::numeric / (1 + abs(ln(p_guess) - ln(p_answer))))::integer;
end;
$$;

-- |G - A| / A * 100, stored with 6 decimal places.
create or replace function pricele.percentage_error(p_guess numeric, p_answer numeric)
returns numeric
language sql
immutable
set search_path = ''
as $$
  select round((abs(p_guess - p_answer) * 100)::numeric(60, 20) / p_answer, 6);
$$;

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create or replace function pricele.is_admin(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_user_id is not null and exists (
    select 1 from public.user_roles where user_id = p_user_id and role = 'admin'
  );
$$;

create or replace function pricele.is_suspended(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.user_moderation where user_id = p_user_id and suspended_at is not null
  );
$$;

-- Fixed-window limiter. Returns true when the hit is allowed.
create or replace function pricele.rate_limit(p_bucket text, p_window_seconds integer, p_max integer)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_window timestamptz;
  v_hits integer;
begin
  if p_bucket is null or char_length(p_bucket) > 200 or p_window_seconds < 1 or p_max < 1 then
    raise exception 'PRICELE_INVALID: bad rate limit arguments';
  end if;
  v_window := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  insert into public.rate_limits (bucket, window_start, hits)
  values (p_bucket, v_window, 1)
  on conflict (bucket, window_start) do update set hits = public.rate_limits.hits + 1
  returning hits into v_hits;
  -- Opportunistic cleanup of old windows (cheap, indexed).
  if random() < 0.01 then
    delete from public.rate_limits where window_start < now() - interval '1 day';
  end if;
  return v_hits <= p_max;
end;
$$;

-- Guest sessions -------------------------------------------------------------
create or replace function pricele.create_guest_session(p_token_hash bytea, p_ttl_days integer default 30)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if p_token_hash is null or octet_length(p_token_hash) <> 32 then
    raise exception 'PRICELE_INVALID: token hash must be 32 bytes';
  end if;
  if p_ttl_days not between 1 and 90 then
    raise exception 'PRICELE_INVALID: ttl out of range';
  end if;
  insert into public.guest_sessions (token_hash, expires_at)
  values (p_token_hash, now() + make_interval(days => p_ttl_days))
  returning id into v_id;
  return v_id;
end;
$$;

-- Returns the guest session id when the token is valid (unexpired, unrevoked, unclaimed).
create or replace function pricele.resolve_guest(p_token_hash bytea)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select id from public.guest_sessions
   where p_token_hash is not null
     and token_hash = p_token_hash
     and expires_at > now()
     and revoked_at is null
     and claimed_at is null;
$$;

-- Resolves (user | guest) identity. Raises on invalid combinations.
create or replace function pricele.resolve_player(p_user_id uuid, p_guest_hash bytea, out o_user_id uuid, out o_guest_id uuid)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_user_id is not null then
    if not exists (select 1 from public.profiles where id = p_user_id) then
      raise exception 'PRICELE_UNAUTHORIZED: unknown user';
    end if;
    o_user_id := p_user_id;
    return;
  end if;
  if p_guest_hash is not null then
    o_guest_id := pricele.resolve_guest(p_guest_hash);
    if o_guest_id is null then
      raise exception 'PRICELE_GUEST_EXPIRED: guest session is invalid or expired';
    end if;
    return;
  end if;
  raise exception 'PRICELE_UNAUTHORIZED: no player identity';
end;
$$;

-- Answer reveal payload for a question (only ever returned after an attempt exists,
-- or for an archive question whose game date has passed).
create or replace function pricele.reveal_payload(p_question_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'answer', qa.answer_amount::text,
    'answerDefinition', qa.answer_definition,
    'referenceDate', qa.reference_date,
    'referencePeriod', qa.reference_period,
    'explanation', qa.explanation,
    'sources', coalesce((
      select jsonb_agg(jsonb_build_object(
        'title', s.title, 'publisher', s.publisher, 'url', s.source_url, 'publishedAt', s.published_at
      ) order by s.created_at)
      from public.question_sources s where s.question_id = qa.question_id
    ), '[]'::jsonb),
    'corrections', coalesce((
      select jsonb_agg(jsonb_build_object(
        'oldAnswer', c.old_answer::text, 'newAnswer', c.new_answer::text,
        'reason', c.reason, 'sourceUrl', c.source_url, 'correctedAt', c.created_at
      ) order by c.created_at)
      from public.question_corrections c where c.question_id = qa.question_id
    ), '[]'::jsonb)
  )
  from public.question_answers qa
  where qa.question_id = p_question_id;
$$;

create or replace function pricele.attempt_payload(
  p_guess numeric, p_answer numeric, p_score integer, p_error numeric, p_submitted timestamptz
)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select jsonb_build_object(
    'guess', p_guess::text,
    'answerSnapshot', p_answer::text,
    'score', p_score,
    'percentageError', p_error::text,
    'submittedAt', p_submitted
  );
$$;

-- Recompute a user's daily result for a set from authoritative attempts.
-- Creates/updates the row when all three are complete; removes it otherwise.
create or replace function pricele.refresh_daily_result(p_user_id uuid, p_set_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
  v_easy integer; v_medium integer; v_hard integer;
  v_perfect integer;
  v_completed timestamptz;
  v_date date;
begin
  select count(*),
         coalesce(sum(a.score) filter (where dsq.position = 1), 0),
         coalesce(sum(a.score) filter (where dsq.position = 2), 0),
         coalesce(sum(a.score) filter (where dsq.position = 3), 0),
         count(*) filter (where a.score = 1000),
         max(a.submitted_at)
    into v_count, v_easy, v_medium, v_hard, v_perfect, v_completed
    from public.official_attempts a
    join public.daily_set_questions dsq
      on dsq.daily_set_id = a.daily_set_id and dsq.question_id = a.question_id
   where a.user_id = p_user_id and a.daily_set_id = p_set_id;

  if v_count = 3 then
    select game_date into v_date from public.daily_sets where id = p_set_id;
    insert into public.daily_results
      (daily_set_id, game_date, user_id, total_score, easy_score, medium_score, hard_score,
       perfect_guess_count, completed_at)
    values (p_set_id, v_date, p_user_id, v_easy + v_medium + v_hard, v_easy, v_medium, v_hard,
            v_perfect, v_completed)
    on conflict (daily_set_id, user_id) do update set
      total_score = excluded.total_score,
      easy_score = excluded.easy_score,
      medium_score = excluded.medium_score,
      hard_score = excluded.hard_score,
      perfect_guess_count = excluded.perfect_guess_count,
      completed_at = excluded.completed_at,
      game_date = excluded.game_date;
  else
    delete from public.daily_results where user_id = p_user_id and daily_set_id = p_set_id;
  end if;
end;
$$;

-- ---------------------------------------------------------------------------
-- Streaks: consecutive *game days* (dates that had a live daily set), counted on
-- America/New_York dates. Days with no published set neither extend nor break a streak.
-- An unfinished current day never resets a streak before it ends.
-- ---------------------------------------------------------------------------
create or replace function pricele.user_streaks(p_user_id uuid, out current_streak integer, out best_streak integer)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_today date := pricele.current_game_date();
  v_latest_idx bigint;
  v_latest_date date;
begin
  current_streak := 0;
  best_streak := 0;

  with game_days as (
    select ds.id, ds.game_date, row_number() over (order by ds.game_date) as idx
      from public.daily_sets ds
     where ds.status in ('scheduled', 'published') and ds.game_date <= v_today
  ),
  done as (
    select gd.idx, gd.idx - row_number() over (order by gd.idx) as grp
      from game_days gd
      join public.daily_results dr on dr.daily_set_id = gd.id and dr.user_id = p_user_id
  ),
  islands as (
    select grp, count(*) as len, max(idx) as last_idx from done group by grp
  )
  select coalesce(max(len), 0) into best_streak from islands;

  select max(idx), max(game_date) into v_latest_idx, v_latest_date from (
    select row_number() over (order by ds.game_date) as idx, ds.game_date
      from public.daily_sets ds
     where ds.status in ('scheduled', 'published') and ds.game_date <= v_today
  ) t;

  if v_latest_idx is null then
    return;
  end if;

  with game_days as (
    select ds.id, ds.game_date, row_number() over (order by ds.game_date) as idx
      from public.daily_sets ds
     where ds.status in ('scheduled', 'published') and ds.game_date <= v_today
  ),
  done as (
    select gd.idx, gd.idx - row_number() over (order by gd.idx) as grp
      from game_days gd
      join public.daily_results dr on dr.daily_set_id = gd.id and dr.user_id = p_user_id
  ),
  islands as (
    select grp, count(*) as len, max(idx) as last_idx from done group by grp
  )
  select coalesce(max(len) filter (
           where last_idx = v_latest_idx
              or (last_idx = v_latest_idx - 1 and v_latest_date = v_today)
         ), 0)
    into current_streak
    from islands;
end;
$$;

-- ---------------------------------------------------------------------------
-- Game state for a date. For today: official play state. Answers are included
-- only for questions the player has already submitted.
-- ---------------------------------------------------------------------------
create or replace function pricele.game_state(p_user_id uuid, p_guest_hash bytea, p_date date default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_today date := pricele.current_game_date();
  v_date date := coalesce(p_date, v_today);
  v_set record;
  v_guest_id uuid;
  v_questions jsonb;
begin
  if p_user_id is null and p_guest_hash is not null then
    v_guest_id := pricele.resolve_guest(p_guest_hash);
  end if;

  select id, game_date into v_set
    from public.daily_sets
   where game_date = v_date and status in ('scheduled', 'published') and game_date <= v_today;

  if v_set.id is null then
    return jsonb_build_object('available', false, 'gameDate', v_date, 'today', v_today);
  end if;

  select jsonb_agg(q order by (q->>'position')::int) into v_questions
  from (
    select jsonb_build_object(
      'id', qn.id,
      'position', dsq.position,
      'difficulty', qn.difficulty,
      'prompt', qn.prompt,
      'context', qn.context,
      'imageUrl', qn.image_url,
      'imageAlt', qn.image_alt,
      'imageCredit', qn.image_credit,
      'category', c.name,
      'isSample', qn.is_sample,
      'attempt', case when a.id is null then null else
        pricele.attempt_payload(a.guess_amount, a.answer_snapshot, a.score, a.absolute_percentage_error, a.submitted_at)
        || jsonb_build_object('reveal', pricele.reveal_payload(qn.id))
      end
    ) as q
    from public.daily_set_questions dsq
    join public.questions qn on qn.id = dsq.question_id
    join public.categories c on c.id = qn.category_id
    left join public.official_attempts a
      on a.question_id = qn.id
     and ((p_user_id is not null and a.user_id = p_user_id)
       or (v_guest_id is not null and a.guest_session_id = v_guest_id))
    where dsq.daily_set_id = v_set.id
  ) s;

  return jsonb_build_object(
    'available', true,
    'setId', v_set.id,
    'gameDate', v_set.game_date,
    'today', v_today,
    'isToday', v_set.game_date = v_today,
    'questions', coalesce(v_questions, '[]'::jsonb)
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- Official guess submission — atomic and idempotent.
-- Returns {ok:true, duplicate:bool, attempt:{...reveal}, progress:{...}} or {ok:false, error:code}.
-- ---------------------------------------------------------------------------
create or replace function pricele.submit_official_guess(
  p_user_id uuid, p_guest_hash bytea, p_question_id uuid, p_guess numeric
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_today date := pricele.current_game_date();
  v_user uuid;
  v_guest uuid;
  v_set_id uuid;
  v_set_date date;
  v_answer numeric(20, 2);
  v_verified text;
  v_score integer;
  v_error numeric;
  v_attempt public.official_attempts%rowtype;
  v_duplicate boolean := false;
  v_answered integer;
  v_total integer;
begin
  if p_guess is null or p_guess <= 0 or p_guess > pricele.max_amount() or p_guess <> round(p_guess, 2) then
    return jsonb_build_object('ok', false, 'error', 'invalid_guess');
  end if;

  begin
    select o_user_id, o_guest_id into v_user, v_guest from pricele.resolve_player(p_user_id, p_guest_hash);
  exception when others then
    if sqlerrm like 'PRICELE_GUEST_EXPIRED%' then
      return jsonb_build_object('ok', false, 'error', 'guest_expired');
    end if;
    return jsonb_build_object('ok', false, 'error', 'unauthorized');
  end;

  if v_user is not null and pricele.is_suspended(v_user) then
    return jsonb_build_object('ok', false, 'error', 'suspended');
  end if;

  if not exists (select 1 from public.questions where id = p_question_id) then
    return jsonb_build_object('ok', false, 'error', 'question_not_found');
  end if;

  select ds.id, ds.game_date into v_set_id, v_set_date
    from public.daily_set_questions dsq
    join public.daily_sets ds on ds.id = dsq.daily_set_id
   where dsq.question_id = p_question_id
     and ds.status in ('scheduled', 'published');

  if v_set_id is null then
    return jsonb_build_object('ok', false, 'error', 'set_not_published');
  end if;
  if v_set_date <> v_today then
    return jsonb_build_object('ok', false, 'error', 'not_current_set');
  end if;

  -- Serialize submissions per player+set so completion is computed exactly once.
  perform pg_advisory_xact_lock(
    hashtextextended(coalesce(v_user::text, 'g:' || v_guest::text) || ':' || v_set_id::text, 0)
  );

  select * into v_attempt from public.official_attempts
   where question_id = p_question_id
     and ((v_user is not null and user_id = v_user) or (v_guest is not null and guest_session_id = v_guest));

  if v_attempt.id is not null then
    v_duplicate := true;
  else
    select answer_amount, verification_status into v_answer, v_verified
      from public.question_answers where question_id = p_question_id;
    if v_answer is null or v_verified <> 'verified' then
      return jsonb_build_object('ok', false, 'error', 'set_not_published');
    end if;

    v_score := pricele.score(p_guess, v_answer);
    v_error := pricele.percentage_error(p_guess, v_answer);

    insert into public.official_attempts
      (daily_set_id, question_id, user_id, guest_session_id, guess_amount, answer_snapshot,
       score, absolute_percentage_error, scoring_version, submitted_at)
    values
      (v_set_id, p_question_id, v_user, v_guest, p_guess, v_answer,
       v_score, v_error, pricele.scoring_version(), now())
    on conflict do nothing
    returning * into v_attempt;

    if v_attempt.id is null then
      -- Lost a race with an identical request: return the stored attempt.
      v_duplicate := true;
      select * into v_attempt from public.official_attempts
       where question_id = p_question_id
         and ((v_user is not null and user_id = v_user) or (v_guest is not null and guest_session_id = v_guest));
    end if;

    if v_user is not null then
      perform pricele.refresh_daily_result(v_user, v_set_id);
    end if;
  end if;

  if v_guest is not null then
    update public.guest_sessions set last_seen_at = now() where id = v_guest;
  end if;

  select count(*), coalesce(sum(score), 0) into v_answered, v_total
    from public.official_attempts
   where daily_set_id = v_set_id
     and ((v_user is not null and user_id = v_user) or (v_guest is not null and guest_session_id = v_guest));

  return jsonb_build_object(
    'ok', true,
    'duplicate', v_duplicate,
    'attempt', pricele.attempt_payload(v_attempt.guess_amount, v_attempt.answer_snapshot, v_attempt.score,
                                       v_attempt.absolute_percentage_error, v_attempt.submitted_at)
               || jsonb_build_object('questionId', p_question_id, 'reveal', pricele.reveal_payload(p_question_id)),
    'progress', jsonb_build_object('answered', v_answered, 'total', v_total, 'completed', v_answered = 3,
                                   'setId', v_set_id, 'gameDate', v_set_date)
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- Practice (archive) guesses. Stored separately; never touch official aggregates.
-- ---------------------------------------------------------------------------
create or replace function pricele.submit_practice_guess(
  p_user_id uuid, p_guest_hash bytea, p_question_id uuid, p_guess numeric
)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_today date := pricele.current_game_date();
  v_user uuid;
  v_guest uuid;
  v_set_id uuid;
  v_set_date date;
  v_answer numeric(20, 2);
  v_row public.practice_attempts%rowtype;
  v_duplicate boolean := false;
begin
  if p_guess is null or p_guess <= 0 or p_guess > pricele.max_amount() or p_guess <> round(p_guess, 2) then
    return jsonb_build_object('ok', false, 'error', 'invalid_guess');
  end if;

  begin
    select o_user_id, o_guest_id into v_user, v_guest from pricele.resolve_player(p_user_id, p_guest_hash);
  exception when others then
    if sqlerrm like 'PRICELE_GUEST_EXPIRED%' then
      return jsonb_build_object('ok', false, 'error', 'guest_expired');
    end if;
    return jsonb_build_object('ok', false, 'error', 'unauthorized');
  end;

  select ds.id, ds.game_date into v_set_id, v_set_date
    from public.daily_set_questions dsq
    join public.daily_sets ds on ds.id = dsq.daily_set_id
   where dsq.question_id = p_question_id and ds.status in ('scheduled', 'published');

  if v_set_id is null then
    return jsonb_build_object('ok', false, 'error', 'question_not_found');
  end if;
  if v_set_date >= v_today then
    return jsonb_build_object('ok', false, 'error', 'not_archived');
  end if;

  -- An official result always wins; practice never replaces it.
  if exists (
    select 1 from public.official_attempts
     where question_id = p_question_id
       and ((v_user is not null and user_id = v_user) or (v_guest is not null and guest_session_id = v_guest))
  ) then
    return jsonb_build_object('ok', false, 'error', 'official_exists');
  end if;

  select * into v_row from public.practice_attempts
   where question_id = p_question_id
     and ((v_user is not null and user_id = v_user) or (v_guest is not null and guest_session_id = v_guest));

  if v_row.id is not null then
    v_duplicate := true;
  else
    select answer_amount into v_answer from public.question_answers where question_id = p_question_id;
    insert into public.practice_attempts
      (daily_set_id, question_id, user_id, guest_session_id, guess_amount, answer_snapshot, score,
       absolute_percentage_error, scoring_version)
    values
      (v_set_id, p_question_id, v_user, v_guest, p_guess, v_answer, pricele.score(p_guess, v_answer),
       pricele.percentage_error(p_guess, v_answer), pricele.scoring_version())
    on conflict do nothing
    returning * into v_row;
    if v_row.id is null then
      v_duplicate := true;
      select * into v_row from public.practice_attempts
       where question_id = p_question_id
         and ((v_user is not null and user_id = v_user) or (v_guest is not null and guest_session_id = v_guest));
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'duplicate', v_duplicate,
    'attempt', pricele.attempt_payload(v_row.guess_amount, v_row.answer_snapshot, v_row.score,
                                       v_row.absolute_percentage_error, v_row.submitted_at)
               || jsonb_build_object('questionId', p_question_id, 'practice', true,
                                     'reveal', pricele.reveal_payload(p_question_id))
  );
end;
$$;

-- Reveal an archive answer without guessing (past dates only).
create or replace function pricele.reveal_archive_answer(p_question_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.daily_set_questions dsq
      join public.daily_sets ds on ds.id = dsq.daily_set_id
     where dsq.question_id = p_question_id
       and ds.status in ('scheduled', 'published')
       and ds.game_date < pricele.current_game_date()
  ) then
    return jsonb_build_object('ok', false, 'error', 'not_archived');
  end if;
  return jsonb_build_object('ok', true, 'reveal', pricele.reveal_payload(p_question_id));
end;
$$;

-- Archive set detail: official + practice attempts for the viewer. Past dates only.
create or replace function pricele.archive_state(p_user_id uuid, p_guest_hash bytea, p_date date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_today date := pricele.current_game_date();
  v_set record;
  v_guest uuid;
  v_questions jsonb;
begin
  if p_user_id is null and p_guest_hash is not null then
    v_guest := pricele.resolve_guest(p_guest_hash);
  end if;

  select id, game_date into v_set from public.daily_sets
   where game_date = p_date and status in ('scheduled', 'published') and game_date < v_today;
  if v_set.id is null then
    return jsonb_build_object('available', false, 'gameDate', p_date, 'today', v_today);
  end if;

  select jsonb_agg(q order by (q->>'position')::int) into v_questions
  from (
    select jsonb_build_object(
      'id', qn.id,
      'position', dsq.position,
      'difficulty', qn.difficulty,
      'prompt', qn.prompt,
      'context', qn.context,
      'imageUrl', qn.image_url,
      'imageAlt', qn.image_alt,
      'imageCredit', qn.image_credit,
      'category', c.name,
      'isSample', qn.is_sample,
      'official', case when oa.id is null then null else
        pricele.attempt_payload(oa.guess_amount, oa.answer_snapshot, oa.score, oa.absolute_percentage_error, oa.submitted_at) end,
      'practice', case when pa.id is null then null else
        pricele.attempt_payload(pa.guess_amount, pa.answer_snapshot, pa.score, pa.absolute_percentage_error, pa.submitted_at) end,
      'reveal', case when oa.id is not null or pa.id is not null then pricele.reveal_payload(qn.id) end
    ) as q
    from public.daily_set_questions dsq
    join public.questions qn on qn.id = dsq.question_id
    join public.categories c on c.id = qn.category_id
    left join public.official_attempts oa on oa.question_id = qn.id
      and ((p_user_id is not null and oa.user_id = p_user_id) or (v_guest is not null and oa.guest_session_id = v_guest))
    left join public.practice_attempts pa on pa.question_id = qn.id
      and ((p_user_id is not null and pa.user_id = p_user_id) or (v_guest is not null and pa.guest_session_id = v_guest))
    where dsq.daily_set_id = v_set.id
  ) s;

  return jsonb_build_object(
    'available', true,
    'setId', v_set.id,
    'gameDate', v_set.game_date,
    'today', v_today,
    'questions', coalesce(v_questions, '[]'::jsonb)
  );
end;
$$;

-- Archive listing with keyset pagination (strictly before p_before, newest first).
create or replace function pricele.archive_list(p_user_id uuid, p_guest_hash bytea, p_before date, p_limit integer)
returns table (
  game_date date,
  set_id uuid,
  difficulties text[],
  official_answered integer,
  official_total integer,
  practice_answered integer
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_today date := pricele.current_game_date();
  v_guest uuid;
begin
  if p_user_id is null and p_guest_hash is not null then
    v_guest := pricele.resolve_guest(p_guest_hash);
  end if;
  return query
  select ds.game_date,
         ds.id,
         array(select q.difficulty from public.daily_set_questions d2
                 join public.questions q on q.id = d2.question_id
                where d2.daily_set_id = ds.id order by d2.position),
         (select count(*)::int from public.official_attempts a where a.daily_set_id = ds.id
            and ((p_user_id is not null and a.user_id = p_user_id) or (v_guest is not null and a.guest_session_id = v_guest))),
         (select coalesce(sum(a.score), 0)::int from public.official_attempts a where a.daily_set_id = ds.id
            and ((p_user_id is not null and a.user_id = p_user_id) or (v_guest is not null and a.guest_session_id = v_guest))),
         (select count(*)::int from public.practice_attempts a where a.daily_set_id = ds.id
            and ((p_user_id is not null and a.user_id = p_user_id) or (v_guest is not null and a.guest_session_id = v_guest)))
    from public.daily_sets ds
   where ds.status in ('scheduled', 'published')
     and ds.game_date < v_today
     and (p_before is null or ds.game_date < p_before)
   order by ds.game_date desc
   limit least(greatest(coalesce(p_limit, 20), 1), 60);
end;
$$;

-- ---------------------------------------------------------------------------
-- Leaderboards. Ranking: total desc, perfect desc, hard desc, final submission asc.
-- rank() gives equal positions only when all four tie-break values are identical;
-- display order then falls back to username (deterministic, not a competitive advantage).
-- Suspended users are excluded. Private profiles appear without their username.
-- ---------------------------------------------------------------------------
create or replace function pricele.leaderboard_daily(p_date date, p_limit integer default 50, p_offset integer default 0)
returns table (
  rank bigint, user_id uuid, username text, display_name text, avatar_url text, is_public boolean,
  total_score integer, easy_score integer, medium_score integer, hard_score integer,
  perfect_guesses integer, completed_at timestamptz, participants bigint
)
language sql
stable
security definer
set search_path = ''
as $$
  select * from (
    select rank() over (order by dr.total_score desc, dr.perfect_guess_count desc, dr.hard_score desc, dr.completed_at asc),
           dr.user_id,
           case when p.is_public then p.username end,
           case when p.is_public then p.display_name end,
           case when p.is_public then p.avatar_url end,
           p.is_public,
           dr.total_score, dr.easy_score, dr.medium_score, dr.hard_score,
           dr.perfect_guess_count, dr.completed_at,
           count(*) over ()
      from public.daily_results dr
      join public.profiles p on p.id = dr.user_id
      join public.daily_sets ds on ds.id = dr.daily_set_id and ds.status in ('scheduled', 'published')
     where dr.game_date = p_date
       and not exists (select 1 from public.user_moderation m where m.user_id = dr.user_id and m.suspended_at is not null)
  ) r
  order by 1, 3 nulls last, 2
  limit least(greatest(coalesce(p_limit, 50), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
$$;

-- Period leaderboard over [p_from, p_to] game dates (inclusive). Null bounds = all-time.
create or replace function pricele.leaderboard_period(p_from date, p_to date, p_limit integer default 50, p_offset integer default 0)
returns table (
  rank bigint, user_id uuid, username text, display_name text, avatar_url text, is_public boolean,
  total_score bigint, games_completed bigint, perfect_guesses bigint, hard_score bigint,
  final_submission_at timestamptz, participants bigint
)
language sql
stable
security definer
set search_path = ''
as $$
  with agg as (
    select dr.user_id,
           sum(dr.total_score) as total_score,
           count(*) as games,
           sum(dr.perfect_guess_count) as perfect,
           sum(dr.hard_score) as hard,
           max(dr.completed_at) as final_at
      from public.daily_results dr
      join public.daily_sets ds on ds.id = dr.daily_set_id and ds.status in ('scheduled', 'published')
     where (p_from is null or dr.game_date >= p_from)
       and (p_to is null or dr.game_date <= p_to)
       and not exists (select 1 from public.user_moderation m where m.user_id = dr.user_id and m.suspended_at is not null)
     group by dr.user_id
  )
  select * from (
    select rank() over (order by a.total_score desc, a.perfect desc, a.hard desc, a.final_at asc),
           a.user_id,
           case when p.is_public then p.username end,
           case when p.is_public then p.display_name end,
           case when p.is_public then p.avatar_url end,
           p.is_public,
           a.total_score, a.games, a.perfect, a.hard, a.final_at,
           count(*) over ()
      from agg a
      join public.profiles p on p.id = a.user_id
  ) r
  order by 1, 3 nulls last, 2
  limit least(greatest(coalesce(p_limit, 50), 1), 200) offset greatest(coalesce(p_offset, 0), 0);
$$;

create or replace function pricele.user_daily_rank(p_user_id uuid, p_date date)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object('rank', r.rank, 'participants', r.participants)
    from (
      select dr.user_id,
             rank() over (order by dr.total_score desc, dr.perfect_guess_count desc, dr.hard_score desc, dr.completed_at asc) as rank,
             count(*) over () as participants
        from public.daily_results dr
       where dr.game_date = p_date
         and not exists (select 1 from public.user_moderation m where m.user_id = dr.user_id and m.suspended_at is not null)
    ) r
   where r.user_id = p_user_id;
$$;

-- ---------------------------------------------------------------------------
-- Profiles and statistics
-- ---------------------------------------------------------------------------
create or replace function pricele.profile_stats(p_user_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with res as (
    select * from public.daily_results dr
     where dr.user_id = p_user_id
       and exists (select 1 from public.daily_sets ds where ds.id = dr.daily_set_id and ds.status in ('scheduled', 'published'))
  ),
  att as (
    select a.score, a.absolute_percentage_error, q.difficulty
      from public.official_attempts a
      join public.questions q on q.id = a.question_id
     where a.user_id = p_user_id
  ),
  s as (select * from pricele.user_streaks(p_user_id))
  select jsonb_build_object(
    'totalPoints', (select coalesce(sum(total_score), 0) from res),
    'gamesCompleted', (select count(*) from res),
    'averageDailyScore', (select round(avg(total_score), 1) from res),
    'highestDailyScore', (select max(total_score) from res),
    'questionsAnswered', (select count(*) from att),
    'averageQuestionScore', (select round(avg(score), 1) from att),
    'perfectGuesses', (select count(*) from att where score = 1000),
    'medianPercentageError', (select round(percentile_cont(0.5) within group (order by absolute_percentage_error)::numeric, 2) from att),
    'averagePercentageError', (select round(avg(absolute_percentage_error), 2) from att),
    'byDifficulty', (select coalesce(jsonb_object_agg(difficulty, jsonb_build_object('answered', n, 'averageScore', avg_score)), '{}'::jsonb)
                       from (select difficulty, count(*) as n, round(avg(score), 1) as avg_score from att group by difficulty) d),
    'currentStreak', (select current_streak from s),
    'bestStreak', (select best_streak from s),
    'recent', (select coalesce(jsonb_agg(jsonb_build_object(
                  'gameDate', game_date, 'total', total_score, 'easy', easy_score, 'medium', medium_score, 'hard', hard_score
                ) order by game_date desc), '[]'::jsonb)
                 from (select * from res order by game_date desc limit 14) r)
  );
$$;

create or replace function pricele.get_profile(p_user_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'id', p.id, 'username', p.username, 'displayName', p.display_name, 'avatarUrl', p.avatar_url,
    'isPublic', p.is_public, 'createdAt', p.created_at,
    'isAdmin', pricele.is_admin(p.id), 'isSuspended', pricele.is_suspended(p.id)
  )
  from public.profiles p where p.id = p_user_id;
$$;

create or replace function pricele.public_profile(p_username text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'username', p.username, 'displayName', p.display_name, 'avatarUrl', p.avatar_url,
    'createdAt', p.created_at, 'stats', pricele.profile_stats(p.id)
  )
  from public.profiles p
  where p.username = lower(p_username)
    and p.is_public
    and not pricele.is_suspended(p.id);
$$;

create or replace function pricele.update_profile(p_user_id uuid, p_display_name text, p_avatar_url text, p_is_public boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.profiles
     set display_name = nullif(btrim(p_display_name), ''),
         avatar_url = nullif(btrim(p_avatar_url), ''),
         is_public = coalesce(p_is_public, is_public)
   where id = p_user_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'unauthorized');
  end if;
  return jsonb_build_object('ok', true);
exception when check_violation then
  return jsonb_build_object('ok', false, 'error', 'invalid_input');
end;
$$;

create or replace function pricele.update_username(p_user_id uuid, p_username text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_name text := lower(btrim(p_username));
begin
  if v_name !~ '^[a-z][a-z0-9_]{2,19}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_username');
  end if;
  if exists (select 1 from public.profiles where username = v_name and id <> p_user_id) then
    return jsonb_build_object('ok', false, 'error', 'username_taken');
  end if;
  update public.profiles set username = v_name where id = p_user_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'unauthorized');
  end if;
  return jsonb_build_object('ok', true, 'username', v_name);
exception when unique_violation then
  return jsonb_build_object('ok', false, 'error', 'username_taken');
end;
$$;

create or replace function pricele.username_available(p_username text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select lower(btrim(p_username)) ~ '^[a-z][a-z0-9_]{2,19}$'
     and not exists (select 1 from public.profiles where username = lower(btrim(p_username)));
$$;

-- Deletes the auth user; cascades remove profile, attempts, results and roles.
create or replace function pricele.delete_account(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from auth.users where id = p_user_id;
  return jsonb_build_object('ok', found);
end;
$$;

-- Profile row for every new auth user. Uses the requested username when valid and free,
-- otherwise a generated "player_xxxxxxxx" the user can change later.
create or replace function pricele.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_requested text := lower(btrim(coalesce(new.raw_user_meta_data ->> 'username', '')));
  v_name text;
  v_try integer := 0;
begin
  if v_requested ~ '^[a-z][a-z0-9_]{2,19}$'
     and not exists (select 1 from public.profiles where username = v_requested) then
    v_name := v_requested;
  else
    loop
      v_name := 'player_' || substr(md5(new.id::text || v_try::text), 1, 8);
      exit when not exists (select 1 from public.profiles where username = v_name);
      v_try := v_try + 1;
    end loop;
  end if;
  insert into public.profiles (id, username) values (new.id, v_name)
  on conflict (id) do nothing;
  return new;
exception when unique_violation then
  -- Extremely unlikely race on the requested name: fall back to a generated name.
  insert into public.profiles (id, username)
  values (new.id, 'player_' || substr(md5(new.id::text || clock_timestamp()::text), 1, 8))
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function pricele.handle_new_user();

-- ---------------------------------------------------------------------------
-- Claim guest progress into an authenticated account.
-- Transfers official attempts for each daily set where the user has no attempts of
-- their own, preserving timestamps and answer snapshots. Practice attempts are not
-- transferred. The guest session is consumed (claimed + revoked) atomically.
-- ---------------------------------------------------------------------------
create or replace function pricele.claim_guest_session(p_user_id uuid, p_guest_hash bytea)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_session public.guest_sessions%rowtype;
  v_set record;
  v_sets_transferred integer := 0;
  v_attempts_transferred integer := 0;
  v_sets_skipped integer := 0;
  v_n integer;
begin
  if p_user_id is null or not exists (select 1 from public.profiles where id = p_user_id) then
    return jsonb_build_object('ok', false, 'error', 'unauthorized');
  end if;
  if p_guest_hash is null then
    return jsonb_build_object('ok', false, 'error', 'no_guest_session');
  end if;

  select * into v_session from public.guest_sessions where token_hash = p_guest_hash for update;
  if v_session.id is null then
    return jsonb_build_object('ok', false, 'error', 'no_guest_session');
  end if;
  if v_session.claimed_at is not null then
    return jsonb_build_object('ok', false, 'error', 'already_claimed');
  end if;
  if v_session.revoked_at is not null or v_session.expires_at <= now() then
    return jsonb_build_object('ok', false, 'error', 'guest_expired');
  end if;

  for v_set in
    select distinct a.daily_set_id from public.official_attempts a
     join public.daily_sets ds on ds.id = a.daily_set_id and ds.status in ('scheduled', 'published')
     where a.guest_session_id = v_session.id
  loop
    perform pg_advisory_xact_lock(hashtextextended(p_user_id::text || ':' || v_set.daily_set_id::text, 0));
    if exists (select 1 from public.official_attempts
                where user_id = p_user_id and daily_set_id = v_set.daily_set_id) then
      v_sets_skipped := v_sets_skipped + 1;
      continue;
    end if;
    update public.official_attempts
       set user_id = p_user_id,
           guest_session_id = null,
           claimed_from_guest_session_id = v_session.id
     where guest_session_id = v_session.id and daily_set_id = v_set.daily_set_id;
    get diagnostics v_n = row_count;
    v_attempts_transferred := v_attempts_transferred + v_n;
    v_sets_transferred := v_sets_transferred + 1;
    perform pricele.refresh_daily_result(p_user_id, v_set.daily_set_id);
  end loop;

  update public.guest_sessions
     set claimed_by = p_user_id, claimed_at = now(), revoked_at = now()
   where id = v_session.id;

  return jsonb_build_object('ok', true,
    'setsTransferred', v_sets_transferred,
    'attemptsTransferred', v_attempts_transferred,
    'setsSkipped', v_sets_skipped);
end;
$$;

-- Lightweight summary of a guest session's claimable progress (for the claim prompt).
create or replace function pricele.guest_summary(p_guest_hash bytea)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'valid', gs.id is not null,
    'attempts', (select count(*) from public.official_attempts a where a.guest_session_id = gs.id),
    'sets', (select count(distinct a.daily_set_id) from public.official_attempts a where a.guest_session_id = gs.id)
  )
  from (select pricele.resolve_guest(p_guest_hash) as id) gs;
$$;

-- Player-submitted report about a possibly inaccurate question.
create or replace function pricele.report_question(p_user_id uuid, p_guest_hash bytea, p_question_id uuid, p_message text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_guest uuid;
begin
  if p_user_id is null then
    v_guest := pricele.resolve_guest(p_guest_hash);
    if v_guest is null then
      return jsonb_build_object('ok', false, 'error', 'unauthorized');
    end if;
  end if;
  if not pricele.is_question_live(p_question_id) then
    return jsonb_build_object('ok', false, 'error', 'question_not_found');
  end if;
  insert into public.question_reports (question_id, user_id, guest_session_id, message)
  values (p_question_id, p_user_id, v_guest, btrim(p_message));
  return jsonb_build_object('ok', true);
exception when check_violation then
  return jsonb_build_object('ok', false, 'error', 'invalid_input');
end;
$$;

-- Public share data for a completed day (respects profile visibility).
create or replace function pricele.public_result(p_username text, p_date date)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'username', p.username, 'displayName', p.display_name, 'gameDate', dr.game_date,
    'total', dr.total_score, 'easy', dr.easy_score, 'medium', dr.medium_score, 'hard', dr.hard_score
  )
  from public.profiles p
  join public.daily_results dr on dr.user_id = p.id and dr.game_date = p_date
  where p.username = lower(p_username) and p.is_public and not pricele.is_suspended(p.id);
$$;

-- ==== 20261016000004_admin_functions.sql ====
-- Administrative functions. Each verifies admin role in the database (defense in depth on
-- top of the server-side check) and writes to admin_audit_log.

create or replace function pricele.assert_admin(p_admin uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not pricele.is_admin(p_admin) then
    raise exception 'PRICELE_FORBIDDEN: admin role required' using errcode = '42501';
  end if;
end;
$$;

create or replace function pricele.audit(p_admin uuid, p_action text, p_entity_type text, p_entity_id uuid, p_details jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.admin_audit_log (admin_user_id, action, entity_type, entity_id, details)
  values (p_admin, p_action, p_entity_type, p_entity_id, coalesce(p_details, '{}'::jsonb));
$$;

-- ---------------------------------------------------------------------------
-- Questions
-- ---------------------------------------------------------------------------
-- Create or update a draft/approved question and its answer key.
-- Editing an approved question returns it to draft and clears verification, so it
-- must be re-verified and re-approved. Published questions are rejected (use corrections).
create or replace function pricele.admin_save_question(p_admin uuid, p_id uuid, p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid := p_id;
  v_status text;
  v_amount numeric;
begin
  perform pricele.assert_admin(p_admin);

  begin
    v_amount := nullif(p->>'answerAmount', '')::numeric;
  exception when others then
    return jsonb_build_object('ok', false, 'error', 'invalid_amount');
  end;
  if v_amount is not null and (v_amount <= 0 or v_amount > pricele.max_amount() or v_amount <> round(v_amount, 2)) then
    return jsonb_build_object('ok', false, 'error', 'invalid_amount');
  end if;

  if v_id is null then
    insert into public.questions (prompt, context, difficulty, category_id, image_url, image_alt, image_credit, created_by)
    values (btrim(p->>'prompt'), nullif(btrim(p->>'context'), ''), p->>'difficulty', (p->>'categoryId')::uuid,
            nullif(btrim(p->>'imageUrl'), ''), nullif(btrim(p->>'imageAlt'), ''), nullif(btrim(p->>'imageCredit'), ''),
            p_admin)
    returning id into v_id;
    perform pricele.audit(p_admin, 'question.create', 'question', v_id, jsonb_build_object('difficulty', p->>'difficulty'));
  else
    select status into v_status from public.questions where id = v_id for update;
    if v_status is null then
      return jsonb_build_object('ok', false, 'error', 'not_found');
    end if;
    if v_status in ('published', 'archived') then
      return jsonb_build_object('ok', false, 'error', 'not_editable');
    end if;
    if exists (select 1 from public.daily_set_questions where question_id = v_id) then
      return jsonb_build_object('ok', false, 'error', 'assigned_to_set');
    end if;
    update public.questions
       set prompt = btrim(p->>'prompt'),
           context = nullif(btrim(p->>'context'), ''),
           difficulty = p->>'difficulty',
           category_id = (p->>'categoryId')::uuid,
           image_url = nullif(btrim(p->>'imageUrl'), ''),
           image_alt = nullif(btrim(p->>'imageAlt'), ''),
           image_credit = nullif(btrim(p->>'imageCredit'), ''),
           status = 'draft',
           approved_by = null,
           approved_at = null
     where id = v_id;
    perform pricele.audit(p_admin, 'question.update', 'question', v_id,
      jsonb_build_object('previousStatus', v_status));
  end if;

  if v_amount is not null then
    insert into public.question_answers
      (question_id, answer_amount, answer_definition, reference_date, reference_period, explanation, verification_status)
    values (v_id, v_amount, btrim(p->>'answerDefinition'), nullif(p->>'referenceDate', '')::date,
            nullif(btrim(p->>'referencePeriod'), ''), coalesce(btrim(p->>'explanation'), ''), 'unverified')
    on conflict (question_id) do update set
      answer_amount = excluded.answer_amount,
      answer_definition = excluded.answer_definition,
      reference_date = excluded.reference_date,
      reference_period = excluded.reference_period,
      explanation = excluded.explanation,
      verification_status = 'unverified',
      verified_by = null,
      verified_at = null;
    update public.question_sources set verified_at = null, verified_by = null where question_id = v_id;
  end if;

  return jsonb_build_object('ok', true, 'id', v_id);
exception
  when check_violation or not_null_violation or invalid_text_representation or foreign_key_violation then
    return jsonb_build_object('ok', false, 'error', 'invalid_input', 'detail', sqlerrm);
end;
$$;

create or replace function pricele.admin_add_source(p_admin uuid, p_question_id uuid, p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_status text;
begin
  perform pricele.assert_admin(p_admin);
  select status into v_status from public.questions where id = p_question_id;
  if v_status is null then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  insert into public.question_sources
    (question_id, title, publisher, source_url, published_at, reference_date, supporting_excerpt, verification_notes)
  values (p_question_id, btrim(p->>'title'), btrim(p->>'publisher'), btrim(p->>'url'),
          nullif(p->>'publishedAt', '')::date, nullif(p->>'referenceDate', '')::date,
          nullif(btrim(p->>'supportingExcerpt'), ''), nullif(btrim(p->>'verificationNotes'), ''))
  returning id into v_id;
  -- New evidence on an unpublished question requires re-verification.
  if v_status in ('draft', 'approved') then
    update public.question_answers set verification_status = 'unverified', verified_at = null, verified_by = null
     where question_id = p_question_id and verification_status = 'verified';
    update public.questions set status = 'draft', approved_at = null, approved_by = null
     where id = p_question_id and status = 'approved'
       and not exists (select 1 from public.daily_set_questions where question_id = p_question_id);
  end if;
  perform pricele.audit(p_admin, 'source.add', 'question', p_question_id, jsonb_build_object('sourceId', v_id, 'url', p->>'url'));
  return jsonb_build_object('ok', true, 'id', v_id);
exception
  when check_violation or not_null_violation or invalid_datetime_format then
    return jsonb_build_object('ok', false, 'error', 'invalid_input', 'detail', sqlerrm);
end;
$$;

create or replace function pricele.admin_delete_source(p_admin uuid, p_source_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_qid uuid;
begin
  perform pricele.assert_admin(p_admin);
  delete from public.question_sources where id = p_source_id returning question_id into v_qid;
  if v_qid is null then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  update public.question_answers set verification_status = 'unverified', verified_at = null, verified_by = null
   where question_id = v_qid and verification_status = 'verified';
  update public.questions set status = 'draft', approved_at = null, approved_by = null
   where id = v_qid and status = 'approved'
     and not exists (select 1 from public.daily_set_questions where question_id = v_qid);
  perform pricele.audit(p_admin, 'source.delete', 'question', v_qid, jsonb_build_object('sourceId', p_source_id));
  return jsonb_build_object('ok', true);
exception when raise_exception then
  return jsonb_build_object('ok', false, 'error', 'immutable');
end;
$$;

-- Problems that block verification/publication of a single question.
create or replace function pricele.question_problems(p_question_id uuid)
returns text[]
language sql
stable
security definer
set search_path = ''
as $$
  select array_remove(array[
    case when qa.question_id is null then 'Answer amount is missing' end,
    case when qa.question_id is not null and qa.answer_amount <= 0 then 'Answer must be positive' end,
    case when qa.question_id is not null and char_length(coalesce(qa.answer_definition, '')) < 5 then 'Answer definition is missing' end,
    case when qa.question_id is not null and qa.reference_date is null and qa.reference_period is null
         then 'Reference date or measurement period is missing' end,
    case when qa.question_id is not null and char_length(coalesce(qa.explanation, '')) < 20
         then 'Explanation is missing or too short (20+ characters)' end,
    case when not exists (select 1 from public.question_sources s where s.question_id = q.id)
         then 'At least one source is required' end,
    case when exists (select 1 from public.question_sources s where s.question_id = q.id)
          and not exists (select 1 from public.question_sources s where s.question_id = q.id
                            and (s.supporting_excerpt is not null or s.verification_notes is not null))
         then 'Record a supporting excerpt or verification note for at least one source' end
  ], null)
  from public.questions q
  left join public.question_answers qa on qa.question_id = q.id
  where q.id = p_question_id;
$$;

-- Admin attests that the source(s) support the exact target amount.
create or replace function pricele.admin_verify_answer(p_admin uuid, p_question_id uuid, p_attestation boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_problems text[];
  v_status text;
begin
  perform pricele.assert_admin(p_admin);
  if p_attestation is not true then
    return jsonb_build_object('ok', false, 'error', 'attestation_required');
  end if;
  select status into v_status from public.questions where id = p_question_id;
  if v_status is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if v_status <> 'draft' then return jsonb_build_object('ok', false, 'error', 'not_draft'); end if;
  v_problems := pricele.question_problems(p_question_id);
  if cardinality(v_problems) > 0 then
    return jsonb_build_object('ok', false, 'error', 'incomplete', 'problems', to_jsonb(v_problems));
  end if;
  update public.question_answers
     set verification_status = 'verified', verified_by = p_admin, verified_at = now()
   where question_id = p_question_id;
  update public.question_sources set verified_at = now(), verified_by = p_admin
   where question_id = p_question_id;
  perform pricele.audit(p_admin, 'question.verify', 'question', p_question_id,
    jsonb_build_object('answer', (select answer_amount::text from public.question_answers where question_id = p_question_id)));
  return jsonb_build_object('ok', true);
end;
$$;

create or replace function pricele.admin_set_question_status(p_admin uuid, p_question_id uuid, p_action text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_status text;
  v_verified text;
begin
  perform pricele.assert_admin(p_admin);
  select q.status, qa.verification_status into v_status, v_verified
    from public.questions q left join public.question_answers qa on qa.question_id = q.id
   where q.id = p_question_id for update of q;
  if v_status is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;

  if p_action = 'approve' then
    if v_status <> 'draft' then return jsonb_build_object('ok', false, 'error', 'not_draft'); end if;
    if v_verified is distinct from 'verified' then
      return jsonb_build_object('ok', false, 'error', 'not_verified');
    end if;
    update public.questions set status = 'approved', approved_by = p_admin, approved_at = now() where id = p_question_id;
  elsif p_action = 'unapprove' then
    if v_status <> 'approved' then return jsonb_build_object('ok', false, 'error', 'not_approved'); end if;
    if exists (select 1 from public.daily_set_questions where question_id = p_question_id) then
      return jsonb_build_object('ok', false, 'error', 'assigned_to_set');
    end if;
    update public.questions set status = 'draft', approved_by = null, approved_at = null where id = p_question_id;
  elsif p_action = 'archive' then
    if v_status not in ('draft', 'approved') then return jsonb_build_object('ok', false, 'error', 'not_archivable'); end if;
    if exists (select 1 from public.daily_set_questions where question_id = p_question_id) then
      return jsonb_build_object('ok', false, 'error', 'assigned_to_set');
    end if;
    update public.questions set status = 'archived' where id = p_question_id;
  elsif p_action = 'restore' then
    if v_status <> 'archived' then return jsonb_build_object('ok', false, 'error', 'not_archived'); end if;
    update public.questions set status = 'draft', approved_by = null, approved_at = null where id = p_question_id;
    update public.question_answers set verification_status = 'unverified', verified_by = null, verified_at = null
     where question_id = p_question_id;
  else
    return jsonb_build_object('ok', false, 'error', 'invalid_action');
  end if;
  perform pricele.audit(p_admin, 'question.' || p_action, 'question', p_question_id, '{}'::jsonb);
  return jsonb_build_object('ok', true);
end;
$$;

-- Likely duplicates: trigram similarity on normalized prompt, or a shared source URL.
create or replace function pricele.admin_similar_questions(p_admin uuid, p_question_id uuid, p_text text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_norm text;
  v_result jsonb;
begin
  perform pricele.assert_admin(p_admin);
  if p_question_id is not null then
    select normalized_prompt into v_norm from public.questions where id = p_question_id;
  else
    v_norm := lower(btrim(regexp_replace(regexp_replace(coalesce(p_text, ''), '[^A-Za-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
  end if;
  select coalesce(jsonb_agg(x order by (x->>'similarity')::numeric desc), '[]'::jsonb) into v_result from (
    select jsonb_build_object('id', q.id, 'prompt', q.prompt, 'status', q.status,
             'similarity', round(extensions.similarity(q.normalized_prompt, v_norm)::numeric, 2),
             'reason', 'Similar wording') as x
      from public.questions q
     where q.id is distinct from p_question_id
       and extensions.similarity(q.normalized_prompt, v_norm) >= 0.6
    union all
    select jsonb_build_object('id', q.id, 'prompt', q.prompt, 'status', q.status, 'similarity', 1,
             'reason', 'Shares a source URL')
      from public.questions q
     where p_question_id is not null and q.id <> p_question_id
       and exists (
         select 1 from public.question_sources s1 join public.question_sources s2
           on lower(s1.source_url) = lower(s2.source_url)
          where s1.question_id = p_question_id and s2.question_id = q.id)
    limit 20
  ) t;
  return v_result;
end;
$$;

create or replace function pricele.admin_get_question(p_admin uuid, p_question_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v jsonb;
begin
  perform pricele.assert_admin(p_admin);
  select jsonb_build_object(
    'id', q.id, 'prompt', q.prompt, 'context', q.context, 'difficulty', q.difficulty,
    'categoryId', q.category_id, 'category', c.name, 'status', q.status, 'isSample', q.is_sample,
    'imageUrl', q.image_url, 'imageAlt', q.image_alt, 'imageCredit', q.image_credit,
    'createdAt', q.created_at, 'updatedAt', q.updated_at, 'approvedAt', q.approved_at,
    'approvedBy', (select username from public.profiles where id = q.approved_by),
    'answer', case when qa.question_id is null then null else jsonb_build_object(
      'amount', qa.answer_amount::text, 'definition', qa.answer_definition, 'referenceDate', qa.reference_date,
      'referencePeriod', qa.reference_period, 'explanation', qa.explanation,
      'verificationStatus', qa.verification_status, 'verifiedAt', qa.verified_at,
      'verifiedBy', (select username from public.profiles where id = qa.verified_by)) end,
    'sources', coalesce((select jsonb_agg(jsonb_build_object(
        'id', s.id, 'title', s.title, 'publisher', s.publisher, 'url', s.source_url,
        'publishedAt', s.published_at, 'referenceDate', s.reference_date,
        'supportingExcerpt', s.supporting_excerpt, 'verificationNotes', s.verification_notes,
        'verifiedAt', s.verified_at) order by s.created_at)
      from public.question_sources s where s.question_id = q.id), '[]'::jsonb),
    'problems', to_jsonb(pricele.question_problems(q.id)),
    'dailySet', (select jsonb_build_object('id', ds.id, 'gameDate', ds.game_date, 'status', ds.status)
                   from public.daily_set_questions dsq join public.daily_sets ds on ds.id = dsq.daily_set_id
                  where dsq.question_id = q.id),
    'corrections', coalesce((select jsonb_agg(jsonb_build_object(
        'id', c2.id, 'oldAnswer', c2.old_answer::text, 'newAnswer', c2.new_answer::text, 'reason', c2.reason,
        'sourceUrl', c2.source_url, 'createdAt', c2.created_at,
        'affectedOfficial', c2.affected_official_attempts) order by c2.created_at)
      from public.question_corrections c2 where c2.question_id = q.id), '[]'::jsonb),
    'attemptCount', (select count(*) from public.official_attempts a where a.question_id = q.id)
  ) into v
  from public.questions q
  join public.categories c on c.id = q.category_id
  left join public.question_answers qa on qa.question_id = q.id
  where q.id = p_question_id;
  return v;
end;
$$;

create or replace function pricele.admin_list_questions(
  p_admin uuid, p_status text, p_difficulty text, p_search text, p_limit integer, p_offset integer
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v jsonb;
begin
  perform pricele.assert_admin(p_admin);
  select jsonb_build_object(
    'total', (select count(*) from public.questions q
               where (p_status is null or q.status = p_status)
                 and (p_difficulty is null or q.difficulty = p_difficulty)
                 and (p_search is null or q.prompt ilike '%' || p_search || '%')),
    'items', coalesce(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb)
  ) into v
  from (
    select q.id, q.prompt, q.difficulty, q.status, q.is_sample as "isSample", c.name as category,
           qa.verification_status as "verificationStatus",
           (select count(*) from public.question_sources s where s.question_id = q.id) as "sourceCount",
           cardinality(pricele.question_problems(q.id)) as "problemCount",
           (select ds.game_date from public.daily_set_questions dsq join public.daily_sets ds on ds.id = dsq.daily_set_id
             where dsq.question_id = q.id) as "gameDate",
           q.updated_at as "updatedAt"
      from public.questions q
      join public.categories c on c.id = q.category_id
      left join public.question_answers qa on qa.question_id = q.id
     where (p_status is null or q.status = p_status)
       and (p_difficulty is null or q.difficulty = p_difficulty)
       and (p_search is null or q.prompt ilike '%' || p_search || '%')
     order by q.updated_at desc
     limit least(greatest(coalesce(p_limit, 50), 1), 200) offset greatest(coalesce(p_offset, 0), 0)
  ) t;
  return v;
end;
$$;

-- Questions grouped by source health for the sources review page.
create or replace function pricele.admin_source_review(p_admin uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v jsonb;
begin
  perform pricele.assert_admin(p_admin);
  select jsonb_build_object(
    'problemQuestions', coalesce((select jsonb_agg(jsonb_build_object(
        'id', q.id, 'prompt', q.prompt, 'status', q.status, 'problems', to_jsonb(pricele.question_problems(q.id)))
        order by q.updated_at desc)
      from public.questions q
      where q.status in ('draft', 'approved') and cardinality(pricele.question_problems(q.id)) > 0), '[]'::jsonb),
    'sources', coalesce((select jsonb_agg(jsonb_build_object(
        'id', s.id, 'questionId', s.question_id, 'prompt', q.prompt, 'questionStatus', q.status,
        'title', s.title, 'publisher', s.publisher, 'url', s.source_url, 'publishedAt', s.published_at,
        'hasExcerpt', s.supporting_excerpt is not null, 'verifiedAt', s.verified_at)
        order by s.created_at desc)
      from (select * from public.question_sources order by created_at desc limit 200) s
      join public.questions q on q.id = s.question_id), '[]'::jsonb),
    'reports', coalesce((select jsonb_agg(jsonb_build_object(
        'id', r.id, 'questionId', r.question_id, 'prompt', q.prompt, 'message', r.message,
        'status', r.status, 'createdAt', r.created_at) order by r.created_at desc)
      from (select * from public.question_reports where status = 'open' order by created_at desc limit 100) r
      join public.questions q on q.id = r.question_id), '[]'::jsonb)
  ) into v;
  return v;
end;
$$;

create or replace function pricele.admin_resolve_report(p_admin uuid, p_report_id uuid, p_status text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform pricele.assert_admin(p_admin);
  if p_status not in ('resolved', 'dismissed') then
    return jsonb_build_object('ok', false, 'error', 'invalid_action');
  end if;
  update public.question_reports set status = p_status, resolved_by = p_admin, resolved_at = now()
   where id = p_report_id and status = 'open';
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  perform pricele.audit(p_admin, 'report.' || p_status, 'question_report', p_report_id, '{}'::jsonb);
  return jsonb_build_object('ok', true);
end;
$$;

-- ---------------------------------------------------------------------------
-- Daily sets
-- ---------------------------------------------------------------------------
create or replace function pricele.admin_create_daily_set(p_admin uuid, p_date date)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  perform pricele.assert_admin(p_admin);
  if p_date is null or p_date < pricele.current_game_date() then
    return jsonb_build_object('ok', false, 'error', 'date_in_past');
  end if;
  if p_date > pricele.current_game_date() + 366 then
    return jsonb_build_object('ok', false, 'error', 'date_too_far');
  end if;
  insert into public.daily_sets (game_date, created_by) values (p_date, p_admin)
  on conflict (game_date) do nothing
  returning id into v_id;
  if v_id is null then
    return jsonb_build_object('ok', false, 'error', 'date_taken');
  end if;
  perform pricele.audit(p_admin, 'daily_set.create', 'daily_set', v_id, jsonb_build_object('gameDate', p_date));
  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;

create or replace function pricele.admin_assign_question(p_admin uuid, p_set_id uuid, p_question_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_set_status text;
  v_q record;
  v_pos smallint;
begin
  perform pricele.assert_admin(p_admin);
  select status into v_set_status from public.daily_sets where id = p_set_id for update;
  if v_set_status is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if v_set_status <> 'draft' then return jsonb_build_object('ok', false, 'error', 'set_locked'); end if;

  select q.status, q.difficulty into v_q from public.questions q where q.id = p_question_id;
  if v_q.status is null then return jsonb_build_object('ok', false, 'error', 'question_not_found'); end if;
  if v_q.status <> 'approved' then return jsonb_build_object('ok', false, 'error', 'question_not_approved'); end if;
  if exists (select 1 from public.daily_set_questions where question_id = p_question_id) then
    return jsonb_build_object('ok', false, 'error', 'question_already_used');
  end if;

  v_pos := case v_q.difficulty when 'easy' then 1 when 'medium' then 2 else 3 end;
  delete from public.daily_set_questions where daily_set_id = p_set_id and position = v_pos;
  insert into public.daily_set_questions (daily_set_id, question_id, position) values (p_set_id, p_question_id, v_pos);
  perform pricele.audit(p_admin, 'daily_set.assign', 'daily_set', p_set_id,
    jsonb_build_object('questionId', p_question_id, 'position', v_pos));
  return jsonb_build_object('ok', true, 'position', v_pos);
end;
$$;

create or replace function pricele.admin_unassign_question(p_admin uuid, p_set_id uuid, p_position smallint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform pricele.assert_admin(p_admin);
  if (select status from public.daily_sets where id = p_set_id) is distinct from 'draft' then
    return jsonb_build_object('ok', false, 'error', 'set_locked');
  end if;
  delete from public.daily_set_questions where daily_set_id = p_set_id and position = p_position;
  perform pricele.audit(p_admin, 'daily_set.unassign', 'daily_set', p_set_id, jsonb_build_object('position', p_position));
  return jsonb_build_object('ok', true);
end;
$$;

-- Validation used both for preview and as the publication gate.
create or replace function pricele.validate_daily_set(p_set_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_set public.daily_sets%rowtype;
  v_errors text[] := '{}';
  v_warnings text[] := '{}';
  v_count integer;
  r record;
begin
  select * into v_set from public.daily_sets where id = p_set_id;
  if v_set.id is null then
    return jsonb_build_object('ok', false, 'errors', jsonb_build_array('Daily set not found'), 'warnings', '[]'::jsonb);
  end if;
  if v_set.status <> 'draft' then
    v_errors := v_errors || ('Set is already ' || v_set.status);
  end if;
  if v_set.game_date < pricele.current_game_date() then
    v_errors := v_errors || 'Game date is in the past'::text;
  end if;
  if exists (select 1 from public.daily_sets where game_date = v_set.game_date and id <> v_set.id
               and status in ('scheduled', 'published')) then
    v_errors := v_errors || 'Another set is already published for this date'::text;
  end if;

  select count(*) into v_count from public.daily_set_questions where daily_set_id = p_set_id;
  if v_count <> 3 then
    v_errors := v_errors || format('Set needs exactly 3 questions (has %s)', v_count);
  end if;
  if (select count(distinct question_id) from public.daily_set_questions where daily_set_id = p_set_id) <> v_count then
    v_errors := v_errors || 'Set contains duplicate questions'::text;
  end if;

  for r in
    select dsq.position, q.id, q.difficulty, q.status, q.prompt, q.category_id, qa.verification_status, qa.answer_amount
      from generate_series(1, 3) as gs(pos)
      left join public.daily_set_questions dsq on dsq.daily_set_id = p_set_id and dsq.position = gs.pos
      left join public.questions q on q.id = dsq.question_id
      left join public.question_answers qa on qa.question_id = q.id
     order by gs.pos
  loop
    if r.id is null then
      continue;
    end if;
    if r.position <> (case r.difficulty when 'easy' then 1 when 'medium' then 2 else 3 end) then
      v_errors := v_errors || format('Question %s is in the wrong difficulty position', r.position);
    end if;
    if r.status <> 'approved' then
      v_errors := v_errors || format('Question %s is not approved', r.position);
    end if;
    if r.verification_status is distinct from 'verified' then
      v_errors := v_errors || format('Question %s answer is not verified', r.position);
    end if;
    if r.answer_amount is null or r.answer_amount <= 0 then
      v_errors := v_errors || format('Question %s answer is missing or invalid', r.position);
    end if;
    if cardinality(pricele.question_problems(r.id)) > 0 then
      v_errors := v_errors || format('Question %s: %s', r.position, array_to_string(pricele.question_problems(r.id), '; '));
    end if;
  end loop;

  -- Variety hints (warnings only, never blocking).
  if (select count(distinct q.category_id) from public.daily_set_questions dsq
        join public.questions q on q.id = dsq.question_id where dsq.daily_set_id = p_set_id) < v_count then
    v_warnings := v_warnings || 'Two or more questions share a category'::text;
  end if;
  if exists (
    select 1 from public.daily_set_questions dsq
      join public.questions q on q.id = dsq.question_id
     where dsq.daily_set_id = p_set_id
       and q.category_id in (
         select q2.category_id from public.daily_sets ds2
           join public.daily_set_questions d2 on d2.daily_set_id = ds2.id
           join public.questions q2 on q2.id = d2.question_id
          where ds2.status in ('scheduled', 'published')
            and ds2.game_date between v_set.game_date - 2 and v_set.game_date - 1)
  ) then
    v_warnings := v_warnings || 'A category here also appeared in the previous two days'::text;
  end if;
  if exists (select 1 from public.daily_set_questions dsq join public.questions q on q.id = dsq.question_id
              where dsq.daily_set_id = p_set_id and q.is_sample) then
    v_warnings := v_warnings || 'Set contains sample (development) questions'::text;
  end if;

  return jsonb_build_object('ok', cardinality(v_errors) = 0, 'errors', to_jsonb(v_errors), 'warnings', to_jsonb(v_warnings));
end;
$$;

create or replace function pricele.admin_publish_daily_set(p_admin uuid, p_set_id uuid, p_confirm boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_validation jsonb;
  v_date date;
  v_new_status text;
begin
  perform pricele.assert_admin(p_admin);
  if p_confirm is not true then
    return jsonb_build_object('ok', false, 'error', 'confirmation_required');
  end if;
  -- Lock the set to serialize concurrent publication attempts.
  select game_date into v_date from public.daily_sets where id = p_set_id for update;
  if v_date is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;

  v_validation := pricele.validate_daily_set(p_set_id);
  if not (v_validation->>'ok')::boolean then
    return jsonb_build_object('ok', false, 'error', 'validation_failed', 'validation', v_validation);
  end if;

  v_new_status := case when v_date > pricele.current_game_date() then 'scheduled' else 'published' end;

  update public.questions set status = 'published'
   where id in (select question_id from public.daily_set_questions where daily_set_id = p_set_id);
  update public.daily_sets
     set status = v_new_status, published_at = now(), published_by = p_admin, version = version + 1
   where id = p_set_id;

  perform pricele.audit(p_admin, 'daily_set.publish', 'daily_set', p_set_id,
    jsonb_build_object('gameDate', v_date, 'status', v_new_status,
      'version', (select version from public.daily_sets where id = p_set_id),
      'questionIds', (select jsonb_agg(question_id order by position) from public.daily_set_questions where daily_set_id = p_set_id)));
  return jsonb_build_object('ok', true, 'status', v_new_status);
end;
$$;

-- Withdraw a set only while nobody has played it (future, or zero official attempts).
-- After play begins, inaccuracies are handled with corrections so every player is treated alike.
create or replace function pricele.admin_unpublish_daily_set(p_admin uuid, p_set_id uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_set public.daily_sets%rowtype;
begin
  perform pricele.assert_admin(p_admin);
  select * into v_set from public.daily_sets where id = p_set_id for update;
  if v_set.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if v_set.status not in ('scheduled', 'published') then
    return jsonb_build_object('ok', false, 'error', 'not_published');
  end if;
  if exists (select 1 from public.official_attempts where daily_set_id = p_set_id)
     or exists (select 1 from public.practice_attempts where daily_set_id = p_set_id) then
    return jsonb_build_object('ok', false, 'error', 'already_played');
  end if;
  if char_length(coalesce(btrim(p_reason), '')) < 5 then
    return jsonb_build_object('ok', false, 'error', 'reason_required');
  end if;

  update public.daily_sets set status = 'draft', published_at = null, published_by = null where id = p_set_id;
  perform set_config('pricele.allow_status_change', 'on', true);
  update public.questions set status = 'approved'
   where id in (select question_id from public.daily_set_questions where daily_set_id = p_set_id);
  perform set_config('pricele.allow_status_change', '', true);
  perform pricele.audit(p_admin, 'daily_set.unpublish', 'daily_set', p_set_id,
    jsonb_build_object('gameDate', v_set.game_date, 'reason', p_reason));
  return jsonb_build_object('ok', true);
end;
$$;

create or replace function pricele.admin_delete_daily_set(p_admin uuid, p_set_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_date date;
begin
  perform pricele.assert_admin(p_admin);
  delete from public.daily_sets where id = p_set_id and status = 'draft' returning game_date into v_date;
  if v_date is null then return jsonb_build_object('ok', false, 'error', 'not_deletable'); end if;
  perform pricele.audit(p_admin, 'daily_set.delete', 'daily_set', p_set_id, jsonb_build_object('gameDate', v_date));
  return jsonb_build_object('ok', true);
end;
$$;

create or replace function pricele.admin_list_daily_sets(p_admin uuid, p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v jsonb;
begin
  perform pricele.assert_admin(p_admin);
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', ds.id, 'gameDate', ds.game_date, 'status', ds.status, 'version', ds.version,
    'publishedAt', ds.published_at,
    'publishedBy', (select username from public.profiles where id = ds.published_by),
    'questionCount', (select count(*) from public.daily_set_questions where daily_set_id = ds.id),
    'players', (select count(distinct coalesce(a.user_id, a.guest_session_id)) from public.official_attempts a where a.daily_set_id = ds.id),
    'completions', (select count(*) from public.daily_results dr where dr.daily_set_id = ds.id)
  ) order by ds.game_date desc), '[]'::jsonb) into v
  from public.daily_sets ds
  where (p_from is null or ds.game_date >= p_from) and (p_to is null or ds.game_date <= p_to);
  return v;
end;
$$;

create or replace function pricele.admin_get_daily_set(p_admin uuid, p_set_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v jsonb;
begin
  perform pricele.assert_admin(p_admin);
  select jsonb_build_object(
    'id', ds.id, 'gameDate', ds.game_date, 'status', ds.status, 'version', ds.version,
    'publishedAt', ds.published_at, 'publishedBy', (select username from public.profiles where id = ds.published_by),
    'questions', coalesce((select jsonb_agg(jsonb_build_object(
        'position', dsq.position, 'id', q.id, 'prompt', q.prompt, 'context', q.context, 'difficulty', q.difficulty,
        'category', c.name, 'status', q.status, 'isSample', q.is_sample,
        'answer', qa.answer_amount::text, 'answerDefinition', qa.answer_definition,
        'verificationStatus', qa.verification_status) order by dsq.position)
      from public.daily_set_questions dsq
      join public.questions q on q.id = dsq.question_id
      join public.categories c on c.id = q.category_id
      left join public.question_answers qa on qa.question_id = q.id
      where dsq.daily_set_id = ds.id), '[]'::jsonb),
    'validation', pricele.validate_daily_set(ds.id),
    'candidates', coalesce((select jsonb_agg(jsonb_build_object(
        'id', q.id, 'prompt', q.prompt, 'difficulty', q.difficulty, 'category', c.name, 'isSample', q.is_sample)
        order by q.difficulty, q.approved_at)
      from public.questions q join public.categories c on c.id = q.category_id
      where q.status = 'approved'
        and not exists (select 1 from public.daily_set_questions d where d.question_id = q.id)), '[]'::jsonb),
    'stats', jsonb_build_object(
      'players', (select count(distinct coalesce(a.user_id, a.guest_session_id)) from public.official_attempts a where a.daily_set_id = ds.id),
      'completions', (select count(*) from public.daily_results dr where dr.daily_set_id = ds.id),
      'averageScore', (select round(avg(total_score), 0) from public.daily_results dr where dr.daily_set_id = ds.id))
  ) into v
  from public.daily_sets ds where ds.id = p_set_id;
  return v;
end;
$$;

-- ---------------------------------------------------------------------------
-- Corrections: re-score every official (and practice) attempt for the question with the
-- corrected answer, keep a per-attempt revision trail, and recompute daily results.
-- Streaks and leaderboards are derived from daily_results, so they update automatically.
-- ---------------------------------------------------------------------------
create or replace function pricele.admin_correct_answer(
  p_admin uuid, p_question_id uuid, p_new_answer numeric, p_reason text, p_source_url text, p_confirm boolean
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old numeric(20, 2);
  v_status text;
  v_correction_id uuid;
  v_official integer := 0;
  v_practice integer := 0;
  r record;
  v_score integer;
  v_err numeric;
begin
  perform pricele.assert_admin(p_admin);
  if p_confirm is not true then return jsonb_build_object('ok', false, 'error', 'confirmation_required'); end if;
  if p_new_answer is null or p_new_answer <= 0 or p_new_answer > pricele.max_amount() or p_new_answer <> round(p_new_answer, 2) then
    return jsonb_build_object('ok', false, 'error', 'invalid_amount');
  end if;
  if char_length(coalesce(btrim(p_reason), '')) < 10 then
    return jsonb_build_object('ok', false, 'error', 'reason_required');
  end if;
  if coalesce(p_source_url, '') !~ '^https?://[^\s]+$' then
    return jsonb_build_object('ok', false, 'error', 'source_required');
  end if;

  select q.status, qa.answer_amount into v_status, v_old
    from public.questions q join public.question_answers qa on qa.question_id = q.id
   where q.id = p_question_id
   for update of qa;
  if v_status is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if v_status <> 'published' then return jsonb_build_object('ok', false, 'error', 'not_published'); end if;
  if v_old = p_new_answer then return jsonb_build_object('ok', false, 'error', 'unchanged'); end if;

  insert into public.question_corrections (question_id, old_answer, new_answer, reason, source_url, admin_user_id)
  values (p_question_id, v_old, p_new_answer, btrim(p_reason), btrim(p_source_url), p_admin)
  returning id into v_correction_id;

  perform set_config('pricele.correction_in_progress', 'on', true);
  update public.question_answers set answer_amount = p_new_answer where question_id = p_question_id;
  perform set_config('pricele.correction_in_progress', '', true);

  -- Record the correction source alongside the original sources.
  insert into public.question_sources (question_id, title, publisher, source_url, verification_notes, verified_at, verified_by)
  values (p_question_id, 'Correction source', 'Recorded with correction', btrim(p_source_url), btrim(p_reason), now(), p_admin);

  for r in select * from public.official_attempts where question_id = p_question_id for update loop
    v_score := pricele.score(r.guess_amount, p_new_answer);
    v_err := pricele.percentage_error(r.guess_amount, p_new_answer);
    insert into public.official_attempt_revisions
      (attempt_id, correction_id, old_answer_snapshot, old_score, old_absolute_percentage_error, old_scoring_version,
       new_answer_snapshot, new_score, new_absolute_percentage_error)
    values (r.id, v_correction_id, r.answer_snapshot, r.score, r.absolute_percentage_error, r.scoring_version,
            p_new_answer, v_score, v_err);
    update public.official_attempts
       set answer_snapshot = p_new_answer, score = v_score, absolute_percentage_error = v_err
     where id = r.id;
    if r.user_id is not null then
      perform pricele.refresh_daily_result(r.user_id, r.daily_set_id);
    end if;
    v_official := v_official + 1;
  end loop;

  update public.practice_attempts
     set answer_snapshot = p_new_answer,
         score = pricele.score(guess_amount, p_new_answer),
         absolute_percentage_error = pricele.percentage_error(guess_amount, p_new_answer)
   where question_id = p_question_id;
  get diagnostics v_practice = row_count;

  update public.question_corrections
     set affected_official_attempts = v_official, affected_practice_attempts = v_practice
   where id = v_correction_id;

  perform pricele.audit(p_admin, 'question.correct', 'question', p_question_id,
    jsonb_build_object('correctionId', v_correction_id, 'oldAnswer', v_old::text, 'newAnswer', p_new_answer::text,
                       'affectedOfficial', v_official, 'affectedPractice', v_practice));
  return jsonb_build_object('ok', true, 'correctionId', v_correction_id,
                            'affectedOfficial', v_official, 'affectedPractice', v_practice);
end;
$$;

-- ---------------------------------------------------------------------------
-- Overview, users, audit
-- ---------------------------------------------------------------------------
create or replace function pricele.admin_overview(p_admin uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_today date := pricele.current_game_date();
  v jsonb;
begin
  perform pricele.assert_admin(p_admin);
  select jsonb_build_object(
    'today', v_today,
    'todaySet', (select jsonb_build_object('id', id, 'status', status, 'gameDate', game_date)
                   from public.daily_sets where game_date = v_today),
    'upcoming', coalesce((select jsonb_agg(jsonb_build_object('date', d::date,
        'set', (select jsonb_build_object('id', ds.id, 'status', ds.status,
                  'questionCount', (select count(*) from public.daily_set_questions where daily_set_id = ds.id))
                  from public.daily_sets ds where ds.game_date = d::date)) order by d)
      from generate_series(v_today, v_today + 13, interval '1 day') d), '[]'::jsonb),
    'counts', jsonb_build_object(
      'published', (select count(*) from public.questions where status = 'published'),
      'approvedUnused', (select count(*) from public.questions q where status = 'approved'
                           and not exists (select 1 from public.daily_set_questions d where d.question_id = q.id)),
      'drafts', (select count(*) from public.questions where status = 'draft'),
      'awaitingVerification', (select count(*) from public.questions q
                                 left join public.question_answers qa on qa.question_id = q.id
                                where q.status = 'draft' and coalesce(qa.verification_status, 'unverified') <> 'verified'),
      'sourceProblems', (select count(*) from public.questions q where q.status in ('draft', 'approved')
                           and cardinality(pricele.question_problems(q.id)) > 0),
      'openReports', (select count(*) from public.question_reports where status = 'open')
    ),
    'usage', jsonb_build_object(
      'todayPlayers', (select count(distinct coalesce(a.user_id, a.guest_session_id)) from public.official_attempts a
                         join public.daily_sets ds on ds.id = a.daily_set_id where ds.game_date = v_today),
      'todayCompletions', (select count(*) from public.daily_results where game_date = v_today),
      'registeredUsers', (select count(*) from public.profiles),
      'last7DaysCompletions', (select count(*) from public.daily_results where game_date > v_today - 7)
    ),
    'recentActivity', coalesce((select jsonb_agg(jsonb_build_object(
        'action', l.action, 'entityType', l.entity_type, 'entityId', l.entity_id, 'createdAt', l.created_at,
        'admin', (select username from public.profiles where id = l.admin_user_id)) order by l.created_at desc)
      from (select * from public.admin_audit_log order by created_at desc limit 10) l), '[]'::jsonb)
  ) into v;
  return v;
end;
$$;

create or replace function pricele.admin_search_users(p_admin uuid, p_query text, p_limit integer)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v jsonb;
  v_q text := lower(btrim(coalesce(p_query, '')));
begin
  perform pricele.assert_admin(p_admin);
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v from (
    select jsonb_build_object(
      'id', p.id, 'username', p.username, 'displayName', p.display_name, 'email', u.email,
      'createdAt', p.created_at, 'isPublic', p.is_public,
      'isAdmin', pricele.is_admin(p.id),
      'suspendedAt', m.suspended_at, 'suspensionReason', m.reason,
      'gamesCompleted', (select count(*) from public.daily_results dr where dr.user_id = p.id),
      'lastPlayedAt', (select max(submitted_at) from public.official_attempts a where a.user_id = p.id)
    ) as x
    from public.profiles p
    join auth.users u on u.id = p.id
    left join public.user_moderation m on m.user_id = p.id
    where v_q = '' or p.username like '%' || v_q || '%' or lower(u.email) like v_q || '%'
    order by p.created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
  ) t;
  return v;
end;
$$;

create or replace function pricele.admin_set_suspension(p_admin uuid, p_user_id uuid, p_suspend boolean, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform pricele.assert_admin(p_admin);
  if p_user_id = p_admin then
    return jsonb_build_object('ok', false, 'error', 'cannot_moderate_self');
  end if;
  if not exists (select 1 from public.profiles where id = p_user_id) then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  if p_suspend and char_length(coalesce(btrim(p_reason), '')) < 5 then
    return jsonb_build_object('ok', false, 'error', 'reason_required');
  end if;
  insert into public.user_moderation (user_id, suspended_at, reason, suspended_by)
  values (p_user_id, case when p_suspend then now() end, case when p_suspend then btrim(p_reason) end, p_admin)
  on conflict (user_id) do update set
    suspended_at = excluded.suspended_at, reason = excluded.reason, suspended_by = excluded.suspended_by;
  perform pricele.audit(p_admin, case when p_suspend then 'user.suspend' else 'user.unsuspend' end, 'user', p_user_id,
    jsonb_build_object('reason', p_reason));
  return jsonb_build_object('ok', true);
end;
$$;

create or replace function pricele.admin_audit_log(p_admin uuid, p_limit integer, p_before timestamptz)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v jsonb;
begin
  perform pricele.assert_admin(p_admin);
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', l.id, 'action', l.action, 'entityType', l.entity_type, 'entityId', l.entity_id,
    'details', l.details, 'createdAt', l.created_at,
    'admin', (select username from public.profiles where id = l.admin_user_id)) order by l.created_at desc), '[]'::jsonb)
  into v
  from (select * from public.admin_audit_log
         where p_before is null or created_at < p_before
         order by created_at desc limit least(greatest(coalesce(p_limit, 50), 1), 200)) l;
  return v;
end;
$$;

create or replace function pricele.admin_categories(p_admin uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare v jsonb;
begin
  perform pricele.assert_admin(p_admin);
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'slug', slug, 'isActive', is_active) order by name), '[]'::jsonb)
    into v from public.categories;
  return v;
end;
$$;

create or replace function pricele.admin_add_category(p_admin uuid, p_name text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_slug text := trim(both '-' from regexp_replace(lower(btrim(p_name)), '[^a-z0-9]+', '-', 'g'));
begin
  perform pricele.assert_admin(p_admin);
  insert into public.categories (name, slug) values (btrim(p_name), v_slug) returning id into v_id;
  perform pricele.audit(p_admin, 'category.create', 'category', v_id, jsonb_build_object('name', p_name));
  return jsonb_build_object('ok', true, 'id', v_id);
exception
  when unique_violation then return jsonb_build_object('ok', false, 'error', 'duplicate');
  when check_violation then return jsonb_build_object('ok', false, 'error', 'invalid_input');
end;
$$;

-- Scheduled job: promote scheduled sets whose date has arrived and report coverage.
create or replace function pricele.cron_publication_check()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_today date := pricele.current_game_date();
  v_promoted integer;
begin
  update public.daily_sets set status = 'published'
   where status = 'scheduled' and game_date <= v_today;
  get diagnostics v_promoted = row_count;
  return jsonb_build_object(
    'today', v_today,
    'promoted', v_promoted,
    'todayLive', exists (select 1 from public.daily_sets where game_date = v_today and status in ('scheduled', 'published')),
    'tomorrowReady', exists (select 1 from public.daily_sets where game_date = v_today + 1 and status in ('scheduled', 'published')),
    'missingNext7', (select coalesce(jsonb_agg(d::date order by d), '[]'::jsonb)
                       from generate_series(v_today, v_today + 6, interval '1 day') d
                      where not exists (select 1 from public.daily_sets ds where ds.game_date = d::date
                                          and ds.status in ('scheduled', 'published'))),
    'expiredGuestSessionsRemoved', 0
  );
end;
$$;

-- Admin bootstrap (NOT executable by pricele_app; run by the database owner only).
create or replace function pricele.bootstrap_admin(p_email text, p_allow_additional boolean default false)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid;
begin
  if exists (select 1 from public.user_roles where role = 'admin') and not p_allow_additional then
    return jsonb_build_object('ok', false, 'error', 'admin_already_exists');
  end if;
  select id into v_user from auth.users where lower(email) = lower(btrim(p_email));
  if v_user is null then
    return jsonb_build_object('ok', false, 'error', 'user_not_found');
  end if;
  insert into public.user_roles (user_id, role) values (v_user, 'admin') on conflict do nothing;
  insert into public.admin_audit_log (admin_user_id, action, entity_type, entity_id, details)
  values (null, 'role.grant', 'user', v_user, jsonb_build_object('role', 'admin', 'via', 'bootstrap'));
  return jsonb_build_object('ok', true, 'userId', v_user);
end;
$$;

create or replace function pricele.revoke_admin(p_email text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid;
begin
  select id into v_user from auth.users where lower(email) = lower(btrim(p_email));
  delete from public.user_roles where user_id = v_user and role = 'admin';
  if not found then return jsonb_build_object('ok', false, 'error', 'not_admin'); end if;
  insert into public.admin_audit_log (admin_user_id, action, entity_type, entity_id, details)
  values (null, 'role.revoke', 'user', v_user, jsonb_build_object('role', 'admin', 'via', 'script'));
  return jsonb_build_object('ok', true);
end;
$$;

-- ---------------------------------------------------------------------------
-- Execute privileges: everything in pricele is server-only, except the RLS helpers
-- granted to anon/authenticated in the previous migration. Bootstrap/revoke stay owner-only.
-- ---------------------------------------------------------------------------
revoke all on all functions in schema pricele from public, anon, authenticated;
grant execute on all functions in schema pricele to pricele_app;
revoke execute on function pricele.bootstrap_admin(text, boolean) from pricele_app;
revoke execute on function pricele.revoke_admin(text) from pricele_app;
revoke execute on function pricele.handle_new_user() from pricele_app;
grant execute on function pricele.is_set_live(uuid) to anon, authenticated;
grant execute on function pricele.is_question_live(uuid) to anon, authenticated;
grant execute on function pricele.now() to anon, authenticated;
grant execute on function pricele.current_game_date() to anon, authenticated;

-- ==== 20261017000001_require_item_pictures.sql ====
-- Every question must show a picture of the item being priced.
-- Pictures may be an https:// URL (licensed image) or an image bundled with the site under /items/.

alter table public.questions drop constraint if exists questions_image_url_check;
alter table public.questions add constraint questions_image_url_check check (
  image_url is null or (
    char_length(image_url) <= 500
    and (image_url ~ '^https://[^\s]+$' or image_url ~ '^/items/[a-z0-9-]+\.(svg|png|jpg|jpeg|webp)$')
  )
);

-- A picture and its description are now required before a question can be verified,
-- approved or published (publication re-checks question_problems).
create or replace function pricele.question_problems(p_question_id uuid)
returns text[]
language sql
stable
security definer
set search_path = ''
as $$
  select array_remove(array[
    case when q.image_url is null then 'Add a picture of the item' end,
    case when q.image_url is not null and char_length(coalesce(q.image_alt, '')) < 5
         then 'Describe the picture for screen readers (alt text)' end,
    case when qa.question_id is null then 'Answer amount is missing' end,
    case when qa.question_id is not null and qa.answer_amount <= 0 then 'Answer must be positive' end,
    case when qa.question_id is not null and char_length(coalesce(qa.answer_definition, '')) < 5 then 'Answer definition is missing' end,
    case when qa.question_id is not null and qa.reference_date is null and qa.reference_period is null
         then 'Reference date or measurement period is missing' end,
    case when qa.question_id is not null and char_length(coalesce(qa.explanation, '')) < 20
         then 'Explanation is missing or too short (20+ characters)' end,
    case when not exists (select 1 from public.question_sources s where s.question_id = q.id)
         then 'At least one source is required' end,
    case when exists (select 1 from public.question_sources s where s.question_id = q.id)
          and not exists (select 1 from public.question_sources s where s.question_id = q.id
                            and (s.supporting_excerpt is not null or s.verification_notes is not null))
         then 'Record a supporting excerpt or verification note for at least one source' end
  ], null)
  from public.questions q
  left join public.question_answers qa on qa.question_id = q.id
  where q.id = p_question_id;
$$;

revoke all on function pricele.question_problems(uuid) from public, anon, authenticated;
grant execute on function pricele.question_problems(uuid) to pricele_app;

-- ==== starter questions (supabase/seed.sql) ====
-- STARTER QUESTIONS — real items researched on 2026-10-17 (generated from supabase/starter-questions.json).
-- Every question is inserted as an UNVERIFIED DRAFT. Prices change: an editor must open each
-- source, confirm the amount, and verify/approve it in the admin dashboard before publishing.
-- Pictures are original illustrations shipped with the site under /items/.
-- Idempotent: re-running does not duplicate rows (keyed by slug).

do $$
declare
  r record;
  v_qid uuid;
begin
  for r in
    select * from (values
      ('starter-hefty-trash-bags-20ct', 'easy', 'everyday-products', 'How much is a 20-count box of Hefty Ultra Strong 30-gallon trash bags at Walmart?', 'Black, unscented, 30-gallon, 20 bags. Walmart.com price on October 17, 2026.', '/items/trash-bags.svg', 'Illustration of a box of large black trash bags labeled 20 bags, 30 gallon', 9.12, 'Walmart.com listed price', '2026-10-17', 'Walmart.com listed the Hefty Ultra Strong Multipurpose Large Trash Bags, 30 gallon, 20 count at $9.12 (about 46 cents a bag) on October 17, 2026.', 'Hefty Ultra Strong Multipurpose Large Trash Bags, Black, Unscented, 30 Gallon, 20 Count', 'Walmart', 'https://www.walmart.com/ip/Hefty-Ultra-Strong-Multipurpose-Large-Trash-Bags-Black-Unscented-30-gallon-20-Count/447801822', '$9.12 — 45.6 ¢/count', ''),
      ('starter-mainstays-fleece-throw', 'easy', 'everyday-products', 'How much is a Mainstays fleece throw blanket (50 x 60 in) at Walmart?', 'Mainstays Sage Fleece Throw Blanket, 50" x 60". Walmart.com price on October 17, 2026.', '/items/fleece-blanket.svg', 'Illustration of a folded sage green fleece throw blanket with a size tag', 5.57, 'Walmart.com listed price', '2026-10-17', 'Walmart.com listed the Mainstays Sage Fleece Throw Blanket, 50 x 60 inches, at $5.57 on October 17, 2026. Other colors were listed between about $4 and $6.', 'Mainstays Sage Fleece Throw Blanket 50" x 60" All Ages', 'Walmart', 'https://www.walmart.com/ip/Mainstays-Sage-Fleece-Throw-Blanket-50-x-60/5408835859', '$5.57', ''),
      ('starter-iphone-18-pro', 'easy', 'technology', 'What is the starting price of the new iPhone 18 Pro?', 'Apple''s U.S. starting price at launch (256GB model), before tax or carrier deals.', '/items/phone.svg', 'Illustration of the back of a smartphone with a triple-lens camera', 1199.00, 'Apple''s U.S. starting retail price at launch', '2026-09-09', 'Apple announced the iPhone 18 Pro on September 9, 2026, starting at $1,199 in the U.S. The iPhone 18 Pro Max starts at $1,299.', 'Apple debuts iPhone 18 Pro and iPhone 18 Pro Max', 'Apple Newsroom', 'https://www.apple.com/newsroom/2026/09/apple-debuts-iphone-18-pro-and-iphone-18-pro-max/', 'iPhone 18 Pro ... starts at $1,199 (U.S.)', ''),
      ('starter-costco-hot-dog-combo', 'easy', 'everyday-products', 'How much is the hot dog and drink combo at a Costco food court?', 'The quarter-pound hot dog with a 20 oz soda (or bottled water), U.S. food courts, 2026.', '/items/hot-dog-combo.svg', 'Illustration of a hot dog with mustard next to a red soda cup', 1.50, 'U.S. food court menu price', '2026-04-29', 'Costco''s hot dog and soda combo has cost $1.50 for about 40 years. In 2026 Costco added bottled water as an option at the same price.', 'Costco''s iconic $1.50 hot dog combo debuts new change for the first time in decades', 'WDBJ7 (Gray News)', 'https://www.wdbj7.com/2026/04/29/costcos-iconic-150-hot-dog-combo-debuts-new-change-first-time-decades/', 'The combo will still cost $1.50 whether you choose a 20-ounce soda or a bottle of water.', ''),
      ('starter-nintendo-switch-2', 'easy', 'technology', 'How much does a Nintendo Switch 2 console cost in the U.S. right now?', 'Nintendo''s U.S. price for the standalone console after the September 1, 2026 change.', '/items/handheld-console.svg', 'Illustration of a handheld game console with controllers on each side', 499.99, 'Nintendo''s U.S. retail price for the console', '2026-09-01', 'Nintendo raised the U.S. price of the Switch 2 from $449.99 to $499.99 starting September 1, 2026, citing market conditions.', 'Nintendo Switch 2 to increase price from $449.99 to $499.99 USD September 1st', 'Zelda Universe', 'https://zeldauniverse.net/2026/08/22/nintendo-switch-2-to-increase-price-from-449-99-to-499-99-usd-september-1st/', 'Nintendo already announced plans to increase the price of the Switch 2 starting September 1', ''),
      ('starter-dyson-v15-detect', 'medium', 'everyday-products', 'What is the full price of a Dyson V15 Detect cordless vacuum on Dyson''s website?', 'Dyson V15 Detect, full (non-sale) price on dyson.com, October 2026.', '/items/stick-vacuum.svg', 'Illustration of a cordless stick vacuum with a light on its floor head', 849.99, 'Full price listed on dyson.com', '2026-10-17', 'Dyson''s U.S. site listed the V15 Detect and V15 Detect Absolute at a full price of $849.99 in October 2026. Retailers often discount it.', 'Shop all V15 Detect vacuums', 'Dyson', 'https://www.dyson.com/vacuum-cleaners/sticks/dyson-v15-stick/shop-all', 'Dyson V15 Detect — $849.99', ''),
      ('starter-kitchenaid-artisan', 'medium', 'everyday-products', 'How much is a KitchenAid Artisan 5-quart stand mixer at Walmart?', 'Artisan Series 5 Quart Tilt-Head Stand Mixer (KSM150PS). Walmart.com price on October 17, 2026.', '/items/stand-mixer.svg', 'Illustration of a red tilt-head stand mixer with a steel bowl', 349.99, 'Walmart.com listed price', '2026-10-17', 'Walmart.com listed the KitchenAid Artisan Series 5-Quart Tilt-Head Stand Mixer at $349.99 on October 17, 2026, down from a listed $429.99.', 'KitchenAid Artisan Series 5 Quart Tilt-Head Stand Mixer (KSM150PSBK)', 'Walmart', 'https://www.walmart.com/ip/KitchenAid-Artisan-Series-5-Quart-Tilt-Head-Stand-Mixer-Imperial-Black-KSM150PSBK/15173451', '$349.99 (was $429.99)', ''),
      ('starter-toyota-camry-2027', 'medium', 'everyday-products', 'What is the starting price of a 2027 Toyota Camry?', 'Base Camry LE, manufacturer''s suggested retail price before destination fees.', '/items/sedan.svg', 'Illustration of a silver four-door sedan', 29700.00, 'Starting MSRP of the 2027 Camry LE, before destination', '2026-05-22', 'The 2027 Toyota Camry LE starts at $29,700 before destination fees. Every 2027 Camry is a hybrid, rated up to 51 mpg.', '2027 Toyota Camry Arrives This Fall With Up To 51 MPG', 'AutoGuide', 'https://www.autoguide.com/auto/manufacturers/toyota/2027-toyota-camry-arrives-this-fall-with-up-to-51-mpg-44640241', 'starting at $29,700 before destination fees', ''),
      ('starter-vision-pro-m5', 'medium', 'technology', 'What is the starting price of Apple Vision Pro?', 'Apple Vision Pro with the M5 chip, U.S. starting price (256GB).', '/items/vr-headset.svg', 'Illustration of a mixed-reality headset with a padded strap', 3499.00, 'Apple''s U.S. starting retail price', '2025-10-15', 'Apple updated Vision Pro with the M5 chip in October 2025. It starts at $3,499 in the U.S. with 256GB of storage.', 'Apple Vision Pro updated with an M5 chip and Dual Knit Band', 'MacTech', 'https://www.mactech.com/2025/10/15/apple-vision-pro-updated-with-an-m5-chip-and-dual-knit-band/', 'starts at $3,499 (U.S.), and is available in 256GB, 512GB, and 1TB', ''),
      ('starter-rolex-submariner-date', 'medium', 'luxury-goods', 'What is the store price of a new Rolex Submariner Date in steel?', 'Reference 126610LN (black dial, Oystersteel), U.S. retail list price in 2026, not resale.', '/items/dive-watch.svg', 'Illustration of a steel dive watch with a black dial and rotating bezel', 11350.00, 'U.S. retail list price (MSRP)', '2026-05-11', 'The Rolex Submariner Date 126610LN listed at $11,350 at U.S. retail in 2026. Pre-owned prices are often higher because of waiting lists.', 'How Much Is a Rolex Submariner in 2026?', 'ECI Jewelers', 'https://www.ecijewelers.com/blogs/recent-posts/how-much-is-a-rolex-submariner-2026', '126610LN ... a retail MSRP of $11,350', 'Secondary source. Confirm against rolex.com before publishing.'),
      ('starter-mantle-1952-card', 'hard', 'sports', 'How much did a 1952 Topps Mickey Mantle baseball card sell for at auction in 2022?', 'The SGC 9.5-graded card sold by Heritage Auctions in August 2022, final price.', '/items/baseball-card.svg', 'Illustration of a graded vintage baseball card in a clear case', 12600000.00, 'Final auction price', '2022-08-28', 'Heritage Auctions sold this 1952 Topps Mickey Mantle, graded SGC 9.5, for $12.6 million on August 28, 2022, a record for any sports card or memorabilia at the time.', 'Mickey Mantle 1952 Topps card, the ''finest known example'' of its kind, sells for record $12.6M', 'CBS Sports', 'https://www.cbssports.com/mlb/news/mickey-mantle-1952-topps-card-the-finest-known-example-of-its-kind-sells-for-record-12-6m/', 'sells for record $12.6M', ''),
      ('starter-ruby-slippers', 'hard', 'entertainment', 'How much did a pair of Dorothy''s ruby slippers from The Wizard of Oz sell for at auction?', 'The pair sold by Heritage Auctions on December 7, 2024, final price.', '/items/ruby-slippers.svg', 'Illustration of a pair of sparkly red heeled shoes with bows', 32500000.00, 'Final auction price', '2024-12-07', 'Heritage Auctions sold the ruby slippers Judy Garland wore in The Wizard of Oz for $32.5 million on December 7, 2024, the most ever paid for movie memorabilia at auction.', '''Wizard of Oz'' Ruby Slippers Sell for Record $32.5 Million', 'Antique Trader', 'https://www.antiquetrader.com/auctions/wizard-of-oz-ruby-slippers-sell-for-record-28-million', '$32.5 million ... by far, the most valuable movie memorabilia ever sold at auction', ''),
      ('starter-salvator-mundi', 'hard', 'luxury-goods', 'How much did Leonardo da Vinci''s painting Salvator Mundi sell for at auction?', 'Christie''s New York, November 15, 2017, final price including fees.', '/items/painting.svg', 'Illustration of a Renaissance portrait in an ornate gold frame', 450300000.00, 'Final auction price including the auction house''s fees', '2017-11-15', 'Salvator Mundi sold at Christie''s on November 15, 2017 for $450.3 million with fees (a $400 million hammer price), the most ever paid for a painting.', 'The Last Known Leonardo da Vinci Painting Just Sold', 'Artnet News', 'https://news.artnet.com/market/last-known-leonardo-da-vinci-painting-just-sold-1149032', 'With the auction house''s fees, the final price was $450.3 million.', ''),
      ('starter-sphere-las-vegas', 'hard', 'science-and-infrastructure', 'How much did the Sphere in Las Vegas cost to build?', 'The total construction cost of the venue, which opened in September 2023.', '/items/sphere-venue.svg', 'Illustration of a giant glowing sphere-shaped venue at night', 2300000000.00, 'Total construction cost', '2023-05-11', 'The Sphere''s construction cost grew to about $2.3 billion, making it the most expensive entertainment venue in Las Vegas. It opened on September 29, 2023.', 'Sphere (venue)', 'Wikipedia, citing the Las Vegas Review-Journal', 'https://en.wikipedia.org/wiki/Sphere_(venue)', 'final expected cost of $2.3 billion', ''),
      ('starter-james-webb-telescope', 'hard', 'science-and-infrastructure', 'How much did the James Webb Space Telescope cost NASA?', 'NASA''s total: building it (2003–2021) plus five years of operations, not adjusted for inflation.', '/items/space-telescope.svg', 'Illustration of a space telescope with gold hexagonal mirrors on a sunshield', 9700000000.00, 'NASA''s total development and five-year operations cost', '2021-12-25', 'NASA expects to spend $9.7 billion on Webb: $8.8 billion to build it and $861 million for five years of operations. Europe and Canada contributed separately.', 'How much does the James Webb Space Telescope cost?', 'The Planetary Society', 'https://www.planetary.org/articles/cost-of-the-jwst', '$9.7 billion over 24 years ... $8.8 billion for spacecraft development ... $861 million for five years of operations', '')
    ) as t(slug, difficulty, cat, prompt, context, image, image_alt, amount, definition, ref_date, explanation,
           src_title, src_publisher, src_url, src_excerpt, src_notes)
  loop
    insert into public.questions (slug, prompt, context, difficulty, category_id, image_url, image_alt, image_credit, status, is_sample)
    values (r.slug, r.prompt, r.context, r.difficulty, (select id from public.categories where slug = r.cat),
            r.image, r.image_alt, 'Illustration: Pricele', 'draft', false)
    on conflict (slug) do nothing
    returning id into v_qid;

    if v_qid is not null then
      insert into public.question_answers (question_id, answer_amount, answer_definition, reference_date, explanation)
      values (v_qid, r.amount, r.definition, r.ref_date::date, r.explanation);
      insert into public.question_sources (question_id, title, publisher, source_url, supporting_excerpt, verification_notes)
      values (v_qid, r.src_title, r.src_publisher, r.src_url, r.src_excerpt,
              nullif(concat_ws(' ', 'Researched 2026-10-17; re-check before verifying.', nullif(r.src_notes, '')), ''));
    end if;
  end loop;
end
$$;

-- ==== app password and cron secret ====
create or replace function pg_temp.pricele_finish_setup()
returns table (app_password text, cron_secret text)
language plpgsql
as $$
declare
  v_pw text := encode(extensions.gen_random_bytes(24), 'hex');
begin
  execute format('alter role pricele_app with login password %L', v_pw);
  return query select v_pw, encode(extensions.gen_random_bytes(24), 'hex');
end;
$$;

select * from pg_temp.pricele_finish_setup();
